INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Lying_Prone_Quadriceps', 'Lying Prone Quadriceps', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'expert', 'Lay face down on the floor with your partner kneeling beside you. Flex one knee and raise that leg off the ground, attempting to touch your glutes with your foot. Your partner should hold the knee and ankle. This will be your starting position. Attempt to extend your knee while your partner prevents any actual movement. After 10-20 seconds, relax your muscles as your partner gently pushes the foot towards your glutes, further stretching the quadriceps and hip flexors. After 10-20 seconds, switch'),
('Lying_Rear_Delt_Raise', 'Lying Rear Delt Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'While holding a dumbbell in each hand, lay with your chest down on a flat bench. Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position. Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicular to the torso while keeping them extended throughout the movement. Also'),
('Lying_Supine_Dumbbell_Curl', 'Lying Supine Dumbbell Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench face up while holding a dumbbell in each arm on top of your thighs. Bring the dumbbells to the sides with the arms extended and the palms of the hands facing your thighs (neutral grip). While keeping the arms close to your torso and elbows in, slowly lower your arms (as you keep them extended with a slight bend at the elbows) as far down towards the floor as you can go. Once you cannot go down any further, lock your upper arms in that position and that will be your start'),
('Lying_T-Bar_Row', 'Lying T-Bar Row', 'back', ARRAY['arms','back']::text[], 'machine', 'strength', 'intermediate', 'Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad. Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize. Lift the bar off the rack and extend your arms '),
('Lying_Triceps_Press', 'Lying Triceps Press', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'Lie on a flat bench with either an e-z bar (my preference) or a straight bar placed on the floor behind your head and your feet on the floor. Grab the bar behind you, using a medium overhand (pronated) grip, and raise the bar in front of you at arms length. Tip: The arms should be perpendicular to the torso and the floor. The elbows should be tucked in. This is the starting position. As you breathe in, slowly lower the weight until the bar lightly touches your forehead while keeping the upper ar'),
('Machine_Bench_Press', 'Machine Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Sit down on the Chest Press Machine and select the weight. Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms. Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be a'),
('Machine_Bicep_Curl', 'Machine Bicep Curl', 'arms', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position. Perform the movement by flexing the elbow, pulling your lower arm towards your upper arm. Pause at the top of the movement, and then slowly return the weight to the starting position. Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.'),
('Machine_Preacher_Curls', 'Machine Preacher Curls', 'arms', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Sit down on the Preacher Curl Machine and select the weight. Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position. Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. '),
('Machine_Shoulder_Military_Press', 'Machine Shoulder (Military) Press', 'shoulders', ARRAY['arms']::text[], 'machine', 'strength', 'beginner', 'Sit down on the Shoulder Press Machine and select the weight. Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position. Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second. Lower the handles slowly back to the starting position as you inhale. Repeat for the recommended amount of repetitions.'),
('Machine_Triceps_Extension', 'Machine Triceps Extension', 'arms', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the seat to the appropriate height and make your weight selection. Place your upper arms against the pads and grasp the handles. This will be your starting position. Perform the movement by extending the elbow, pulling your lower arm away from your upper arm. Pause at the completion of the movement, and then slowly return the weight to the starting position. Avoid returning the weight all the way to the stops until the set is complete to keep tension on the muscles being worked.'),
('Medicine_Ball_Chest_Pass', 'Medicine Ball Chest Pass', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'You will need a partner for this exercise. Lacking one, this movement can be performed against a wall. Begin facing your partner holding the medicine ball at your torso with both hands. Pull the ball to your chest, and reverse the motion by extending through the elbows. For sports applications, you can take a step as you throw. Your partner should catch the ball, and throw it back to you. Receive the throw with both hands at chest height.'),
('Medicine_Ball_Full_Twist', 'Medicine Ball Full Twist', 'core', ARRAY['shoulders']::text[], 'other', 'plyometrics', 'beginner', 'For this exercise you will need a medicine ball and a partner. Stand back to back with your partner, spaced 2-3 feet apart. This will be your starting position. Hold the ball in front of the trunk. Open the hips and turn the shoulders at the same time as your partner. For full rotation, you and your partner should twist in the same direction, i.e. counter-clockwise. Pass the ball to your partner, and both of you can now twist in the opposite direction to repeat the procedure.'),
('Medicine_Ball_Scoop_Throw', 'Medicine Ball Scoop Throw', 'shoulders', ARRAY['core','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Assume a semisquat stance with a medicine ball in your hands. Your arms should hang so the ball is near your feet. Begin by thrusting the hips forward as you extend through the legs, jumping up. As you do, swing your arms up and over your head, keeping them extended, releasing the ball at the peak of your movement. The goal is to throw the ball the greatest distance behind you.'),
('Middle_Back_Shrug', 'Middle Back Shrug', 'back', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position. As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms. As you inhale go back to the starting posi'),
('Middle_Back_Stretch', 'Middle Back Stretch', 'back', ARRAY['core','back','back']::text[], 'other', 'stretching', 'beginner', 'Stand so your feet are shoulder width apart and your hands are on your hips. Twist at your waist until you feel a stretch. Hold for 10 to 15 seconds, then twist to the other side.'),
('Mixed_Grip_Chin', 'Mixed Grip Chin', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'expert', 'Using a spacing that is just about 1 inch wider than shoulder width, grab a pull-up bar with the palms of one hand facing forward and the palms of the other hand facing towards you. This will be your starting position. Now start to pull yourself up as you exhale. Tip: With the arm that has the palms facing up concentrate on using the back muscles in order to perform the movement. The elbow of that arm should remain close to the torso. With the other arm that has the palms facing forward, the elb'),
('Monster_Walk', 'Monster Walk', 'legs', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Place a band around both ankles and another around both knees. There should be enough tension that they are tight when your feet are shoulder width apart. To begin, take short steps forward alternating your left and right foot. After several steps, do just the opposite and walk backward to where you started.'),
('Mountain_Climbers', 'Mountain Climbers', 'legs', ARRAY['chest','legs','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position. Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.'),
('Moving_Claw_Series', 'Moving Claw Series', 'legs', ARRAY['legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'This move helps prepare your running form to help you excel at sprinting. As you run, be sure to flex the knee, aiming to kick your glutes as the hip extends. Reload the quad as the leg moves back forward, attacking the ground on the next step. Ensure that as you run, you block with the arms, punching through in a rapid 1-2 motion.'),
('Muscle_Snatch', 'Muscle Snatch', 'legs', ARRAY['legs','back','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a loaded barbell held at the mid thigh position with a wide grip. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the pull by driving through the front of the heels, raising the bar. Transition into the second pull by extending through the hips knees and ankles, driving the bar up as quickly as possi'),
('Muscle_Up', 'Muscle Up', 'back', ARRAY['core','arms','arms','back','shoulders','back','arms']::text[], 'other', 'strength', 'intermediate', 'Grip the rings using a false grip, with the base of your palms on top of the rings. Initiate a pull up by pulling the elbows down to your side, flexing the elbows. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to continue into the dip portion of the movement. Maintaining control and stability, extend through the elbow to complete the mot'),
('Narrow_Stance_Hack_Squats', 'Narrow Stance Hack Squats', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided. Position your legs in the platform using a less than shoulder width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by movin'),
('Narrow_Stance_Leg_Press', 'Narrow Stance Leg Press', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a less-than-shoulder-width narrow stance with the toes slightly pointed out. Your feet should be around 3 inches or less apart. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure tha'),
('Narrow_Stance_Squats', 'Narrow Stance Squats', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a l'),
('Natural_Glute_Ham_Raise', 'Natural Glute Ham Raise', 'legs', ARRAY['legs','legs','back']::text[], 'bodyweight', 'strength', 'intermediate', 'Using the leg pad of a lat pulldown machine or a preacher bench, position yourself so that your ankles are under the pads, knees on the seat, and you are facing away from the machine. You should be upright and maintaining good posture. This will be your starting position. Lower yourself under control until your knees are almost completely straight. Remaining in control, raise yourself back up to the starting position. If you are unable to complete a rep, use a band, a partner, or push off of a b'),
('Neck-SMR', 'Neck-SMR', 'other', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Using a muscle roller or a rolling pin, place the roller behind your head and against your neck. Make sure that you do not place the roller directly against the spine, but turned slightly so that the roller is pressed against the muscles to either side of the spine. This will be your starting position. Starting at the top of your neck, slowly roll down the muscles of your neck, pausing at points of tension for 10-30 seconds.'),
('Neck_Press', 'Neck Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie back on a flat bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your neck. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arm'),
('Oblique_Crunches', 'Oblique Crunches', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put one hand beside your head and the other to the side against the floor. Make sure your feet are elevated and resting on a flat surface. Now lift the shoulder in which your hand is touching your head. Simply elevate your shoulder and body upward until you touch your knee. For example, if you have your right hand besides your head, then you want to elevate your body upwards until your right elb'),
('Oblique_Crunches_-_On_The_Floor', 'Oblique Crunches - On The Floor', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit. Place your left hand behind your head. Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques. Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position. Remember to breathe in during the eccentric (lowering'),
('Olympic_Squat', 'Olympic Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a barbell supported on top of the traps. The chest should be up, and the head facing forward. Adopt a hip width stance with the feet turned out as needed. Descend by flexing the knees, refraining from moving the hips back as much as possible. This requires that the knees travel forward; ensure that they stay aligned with the feet. The goal is to keep the torso as upright as possible. Continue all the way down, keeping the weight on the front of the heel. At the moment the upper legs c'),
('On-Your-Back_Quad_Stretch', 'On-Your-Back Quad Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Lie on a flat bench or step, and hang one leg and arm over the side. Bend the knee and hold the top of the foot. As you do this, be careful not to arch your lower back. Pull the belly button to the spine to stay in neutral. Press your foot down and into your hand. To add the hip stretch, lift the hip of the leg you''re holding up toward the ceiling. Switch sides.'),
('On_Your_Side_Quad_Stretch', 'On Your Side Quad Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Start off by lying on your right side, with your right knee bent at a 90-degree angle resting on the floor in front of you (this stabilizes the torso). Bend your left knee behind you and hold your left foot with your left hand. To stretch your hip flexor, press your left hip forward as you push your left foot back into your hand. Switch sides.'),
('One-Arm_Dumbbell_Row', 'One-Arm Dumbbell Row', 'back', ARRAY['arms','back','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Choose a flat bench and place a dumbbell on each side of it. Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support. Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position. Pull the resistance straight '),
('One-Arm_Flat_Bench_Dumbbell_Flye', 'One-Arm Flat Bench Dumbbell Flye', 'chest', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench with a dumbbell in one hand resting on top of your thigh. The palm of your hand with the dumbbell in it should be at a neutral grip. By using your thighs to help you get the dumbbell up, clean the dumbbell so that you can hold it in front of you with your lifting arm being fully extended. Remember to maintain a neutral grip with this exercise. Your non lifting hand should be to the side holding the flat bench for better support. This will be your starting position. Your '),
('One-Arm_High-Pulley_Cable_Side_Bends', 'One-Arm High-Pulley Cable Side Bends', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to a tower. Move cable to highest pulley position. Stand with side to cable. With one hand, reach up and grab handle with underhand grip. Pull down cable until elbow touches your side and the handle is by your shoulder. Position feet hip-width apart. Place free hand on hip to help gauge pivot point. Keep arm in static position. Contract oblique to bring the weight down in a side crunch. Once you reach maximum contraction, slowly release the weight to the starting positi'),
('One-Arm_Incline_Lateral_Raise', 'One-Arm Incline Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie down sideways on an incline bench press with a dumbbell in the hand. Make sure the shoulder is pressing against the incline bench and the arm is lying across your body with the palm around your navel. Hold a dumbbell in your uppermost arm while keeping it extended in front of you parallel to the floor. This is your starting position. While keeping the dumbbell parallel to the floor at all times, perform a lateral raise. Your arm should travel straight up until it is pointing at the ceiling. '),
('One-Arm_Kettlebell_Clean', 'One-Arm Kettlebell Clean', 'legs', ARRAY['legs','back','shoulders','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place a kettlebell between your feet. As you bend down to grab the kettlebell, push your butt back and keep your eyes looking forward. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. Return the weight to the starting position.'),
('One-Arm_Kettlebell_Clean_and_Jerk', 'One-Arm Kettlebell Clean and Jerk', 'shoulders', ARRAY[]::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, using your body''s momentum to move t'),
('One-Arm_Kettlebell_Floor_Press', 'One-Arm Kettlebell Floor Press', 'chest', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Lie on the floor holding a kettlebell with one hand, with your upper arm supported by the floor. The palm should be facing in. Press the kettlebell straight up toward the ceiling, rotating your wrist. Lower the kettlebell back to the starting position and repeat.'),
('One-Arm_Kettlebell_Jerk', 'One-Arm Kettlebell Jerk', 'shoulders', ARRAY['legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, '),
('One-Arm_Kettlebell_Military_Press_To_The_Side', 'One-Arm Kettlebell Military Press To The Side', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces inward. This will be your starting position. Look at the kettlebell and press it up and out until it is locked out overhead. Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefully for added stability and st'),
('One-Arm_Kettlebell_Para_Press', 'One-Arm Kettlebell Para Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Hold the kettlebell with the elbow out to the side, and press it up and out until it is locked out overhead. Lower the kettlebell back to your shoulder under control and repeat. Make sure to contract your lat, butt, and stomach forcefu'),
('One-Arm_Kettlebell_Push_Press', 'One-Arm Kettlebell Push Press', 'shoulders', ARRAY['legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, '),
('One-Arm_Kettlebell_Row', 'One-Arm Kettlebell Row', 'back', ARRAY['arms','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place a kettlebell in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab the kettlebell and pull it to your stomach, retracting your shoulder blade and flexing the elbow. Keep your back straight. Lower and repeat.'),
('One-Arm_Kettlebell_Snatch', 'One-Arm Kettlebell Snatch', 'shoulders', ARRAY['legs','legs','legs','back','back','arms']::text[], 'kettlebell', 'strength', 'expert', 'Place a kettlebell between your feet. Bend your knees and push your butt back to get in the proper starting position. Look straight ahead and swing the kettlebell back between your legs. Immediately reverse the direction and drive through with your hips and knees, accelerating the kettlebell upward. As the kettlebell rises to your shoulder rotate your hand and punch straight up, using momentum to receive the weight locked out overhead.'),
('One-Arm_Kettlebell_Split_Jerk', 'One-Arm Kettlebell Split Jerk', 'shoulders', ARRAY['legs','legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so, so that the palm faces forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebell overhead to lockout by extending the arms, '),
('One-Arm_Kettlebell_Split_Snatch', 'One-Arm Kettlebell Split Snatch', 'shoulders', ARRAY['legs','legs']::text[], 'kettlebell', 'strength', 'expert', 'Hold a kettlebell in one hand by the handle. Squat towards the floor, and then reverse the motion, extending the hips, knees, and finally the ankles, to raise the kettlebell overhead. After fully extending the body, descend into a lunge position to receive the weights overhead, one leg forward and one leg back. Ensure you drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion. Return to a standing position, holding the weight overhead, and bring the feet toge'),
('One-Arm_Kettlebell_Swings', 'One-Arm Kettlebell Swings', 'legs', ARRAY['legs','legs','back','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', NULL),
('One-Arm_Long_Bar_Row', 'One-Arm Long Bar Row', 'back', ARRAY['arms','back']::text[], 'barbell', 'strength', 'beginner', 'Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end. Stand next to the bar, and take a grip with one hand close to the collar. Using your hips and legs, rise to a standing position. Assume a bent-knee stance with your hips back and your chest up. Your arm should be extended. This will be your starting position. Pull the weight to your side by retracting the shoulder and flexing the elbow. Do not jerk the weight or cheat during the moveme'),
('One-Arm_Medicine_Ball_Slam', 'One-Arm Medicine Ball Slam', 'core', ARRAY['back','shoulders']::text[], 'other', 'strength', 'beginner', 'Start in a standing position with a staggered, athletic stance. Hold a medicine ball in one hand, on the same side as your back leg. This will be your starting position. Begin by winding the arm, raising the medicine ball above your head. As you do so, extend through the hips, knees, and ankles to load up for the slam. At peak extension, flex the shoulders, spine, and hips to throw the ball hard into the ground directly in front of you. Catch the ball on the bounce and continue for the desired n')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('One-Arm_Open_Palm_Kettlebell_Clean', 'One-Arm Open Palm Kettlebell Clean', 'legs', ARRAY['arms','legs','back','legs','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', 'Place one kettlebell between your feet. Grab the handle with one hand and raise the kettlebell rapidly, let it flip so that the ball of the kettlebell lands in the palm of your hand. Throw the kettlebell out in front of you and catch the handle with one hand. Take the kettlebell to the floor and repeat. Make sure to work both arms.'),
('One-Arm_Overhead_Kettlebell_Squats', 'One-Arm Overhead Kettlebell Squats', 'legs', ARRAY['legs','legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'expert', 'Clean and press a kettlebell with one arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulder. Rotate your wrist as you do so. Press the weight overhead by extending through the elbow.This will be your starting position. Looking straight ahead and keeping a kettlebell locked out above you, flex the knees and hips and lower your torso between your legs, keeping your head and chest up. Pause at the bottom position for a sec'),
('One-Arm_Side_Deadlift', 'One-Arm Side Deadlift', 'legs', ARRAY['core','legs','legs','legs','back','back']::text[], 'barbell', 'strength', 'expert', 'Stand to the side of a barbell next to its center. Bend your knees and lower your body until you are able to reach the barbell. Grasp the bar as if you were grabbing a briefcase (palms facing you since the bar is sideways). You may need a wrist wrap if you are using a significant amount of weight. This is your starting position. Use your legs to help lift the barbell up while exhaling. Your arms should extend fully as bring the barbell up until you are in a standing position. Slowly bring the ba'),
('One-Arm_Side_Laterals', 'One-Arm Side Laterals', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance. Stand with a straight torso and have the dumbbell by your side at arm''s length with the palm of the hand facing you. This will be your starting position. While maintaining the torso stationary (no swinging), lift the dumb'),
('One-Legged_Cable_Kickback', 'One-Legged Cable Kickback', 'legs', ARRAY['legs']::text[], 'cable', 'strength', 'intermediate', 'Hook a leather ankle cuff to a low cable pulley and then attach the cuff to your ankle. Face the weight stack from a distance of about two feet, grasping the steel frame for support. While keeping your knees and hips bent slightly and your abs tight, contract your glutes to slowly "kick" the working leg back in a semicircular arc as high as it will comfortably go as you breathe out. Tip: At full extension, squeeze your glutes for a second in order to achieve a peak contraction. Now slowly bring '),
('One_Arm_Against_Wall', 'One Arm Against Wall', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'From a standing position, place a bent arm against a wall or doorway. Slowly lean toward your arm until you feel a stretch in your lats.'),
('One_Arm_Chin-Up', 'One Arm Chin-Up', 'back', ARRAY['arms','arms','back']::text[], 'other', 'strength', 'expert', 'For this exercise, start out by placing a towel around a chin up bar. Grab the chin-up bar with your palm facing you. One hand will be grabbing the chin-up bar and the other will be grabbing the towel. Bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.v Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this '),
('One_Arm_Dumbbell_Bench_Press', 'One Arm Dumbbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench with a dumbbell in one hand on top of your thigh. By using your thigh to help you get the dumbbell up, clean the dumbbell up so that you can hold it in front of you at shoulder width. Use the hand you are not lifting with to help position the dumbbell over you properly. Once at shoulder width, rotate your wrist forward so that the palm of your hand is facing away from you. This will be your starting position. Bring down the weights slowly to your side as you breathe in. '),
('One_Arm_Dumbbell_Preacher_Curl', 'One Arm Dumbbell Preacher Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position. As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to br'),
('One_Arm_Floor_Press', 'One Arm Floor Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'Lie down on a flat surface with your back pressing against the floor or an exercise mat. Make sure your knees are bent. Have a partner hand you the bar on one hand. When starting, your arm should be just about fully extended, similar to the starting position of a barbell bench press. However, this time your grip will be neutral (palms facing your torso). Make sure the hand you are not using to lift the weight is placed by your side. Begin the exercise by lowering the barbell until your elbow tou'),
('One_Arm_Lat_Pulldown', 'One Arm Lat Pulldown', 'back', ARRAY['arms','back']::text[], 'cable', 'strength', 'beginner', 'Select an appropriate weight and adjust the knee pad to help keep you down. Grasp the handle with a pronated grip. This will be your starting position. Pull the handle down, squeezing your elbow to your side as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handle to the starting position. For multiple repetitions, avoid completely returning the weight to keep tension on the muscles being worked.'),
('One_Arm_Pronated_Dumbbell_Triceps_Extension', 'One Arm Pronated Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your feet as a pronated grip is required to perform this exercise. Place your non lifting hand on your bicep for support. Slowly begin to lower the dumbbell down as you breathe in. Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise). Repeat until you '),
('One_Arm_Supinated_Dumbbell_Triceps_Extension', 'One Arm Supinated Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie flat on a bench while holding a dumbbell at arms length. Your arm should be perpendicular to your body. The palm of your hand should be facing towards your face as a supinated grip is required to perform this exercise. Place your non lifting hand on your bicep for support. Slowly begin to lower the dumbbell down as you breathe in. Then, begin lifting the dumbbell upward as you contract the triceps. Remember to breathe out during the concentric (lifting part of the exercise). Repeat until you'),
('One_Half_Locust', 'One Half Locust', 'legs', ARRAY['core','arms','chest']::text[], 'other', 'stretching', 'beginner', 'Lie facedown on the floor. Put your left hand under your left hipbone to pad your hip and pubic bone. Bend your right knee so you can hold the foot in your right hand. Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn''t bother your back, you can try it with both arms and legs at the same time.'),
('One_Handed_Hang', 'One Handed Hang', 'back', ARRAY['arms']::text[], 'other', 'stretching', 'beginner', 'Grab onto a chinup bar with one hand, using a pronated grip. Keep your feet on the floor or a step. Allow the majority of your weight to hang from that hand, while keeping your feet on the ground. Hold for 10-20 seconds and switch sides.'),
('One_Knee_To_Chest', 'One Knee To Chest', 'legs', ARRAY['legs','back']::text[], 'other', 'stretching', 'beginner', 'Start off by lying on the floor. Extend one leg straight and pull the other knee to your chest. Hold under the knee joint to protect the kneecap. Gently tug that knee toward your nose. Switch sides. This stretches the buttocks and lower back of the bent leg and the hip flexor of the straight leg.'),
('One_Leg_Barbell_Squat', 'One Leg Barbell Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'expert', 'Start by standing about 2 to 3 feet in front of a flat bench with your back facing the bench. Have a barbell in front of you on the floor. Tip: Your feet should be shoulder width apart from each other. Bend the knees and use a pronated grip with your hands being wider than shoulder width apart from each other to lift the barbell up until you can rest it on your chest. Then lift the barbell over your head and rest it on the base of your neck. Move one foot back so that your toe is resting on the '),
('Open_Palm_Kettlebell_Clean', 'Open Palm Kettlebell Clean', 'legs', ARRAY['legs','back','legs','shoulders']::text[], 'kettlebell', 'strength', 'expert', 'Place one kettlebell between your feet. Clean the kettlebell by extending through the legs and hips as you raise the kettlebell towards your shoulders. Release the kettlebell as it comes up, and let it flip so that the ball of the kettlebell lands in the palms of your hands. Release the kettlebell out in front of you and catch the handle with both hands. Lower the kettlebell to the starting position and repeat.'),
('Otis-Up', 'Otis-Up', 'core', ARRAY['chest','shoulders','arms']::text[], 'other', 'strength', 'beginner', 'Secure your feet and lay back on the floor. Your knees should be bent. Hold a weight with both hands to your chest. This will be your starting position. Initiate the movement by flexing the hips and spine to raise your torso up from the ground. As you move up, press the weight up so that it is above your head at the top of the movement. Return the weight to your chest as you reverse the sit-up motion, ensuring not to go all the way down to the floor.'),
('Overhead_Cable_Curl', 'Overhead Cable Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'To begin, set a weight that is comfortable on each side of the pulley machine. Note: Make sure that the amount of weight selected is the same on each side. Now adjust the height of the pulleys on each side and make sure that they are positioned at a height higher than that of your shoulders. Stand in the middle of both sides and use an underhand grip (palms facing towards the ceiling) to grab each handle. Your arms should be fully extended and parallel to the floor with your feet positioned shou'),
('Overhead_Lat', 'Overhead Lat', 'back', ARRAY['arms']::text[], 'other', 'stretching', 'expert', 'Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your tricep and wrist. This will be your starting position. Attempt to pull your upper arm to your side as your partner prevents you from doing actually doing so. After 10-20 seconds, relax the arm and allow your partner to further stretch the lat by applying gentle pressure to the tricep. Hold for 10-20 seconds, and then switch'),
('Overhead_Slam', 'Overhead Slam', 'back', ARRAY[]::text[], 'other', 'plyometrics', 'beginner', 'Hold a medine ball with both hands and stand with your feet at shoulder width. This will be your starting position. Initiate the countermovement by raising the ball above your head and fully extending your body. Reverse the motion, slamming the ball into the ground directly in front of you as hard as you can. Receive the ball with both hands on the bounce and repeat the movement.'),
('Overhead_Squat', 'Overhead Squat', 'legs', ARRAY['core','legs','legs','legs','back','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Start out by having a barbell in front of you on the floor. Your feet should be wider than shoulder width apart from each other. Bend the knees and use a pronated grip (palms facing you) to grab the barbell. Your hands should be at a wider than shoulder width apart from each other before lifting. Once you are positioned, lift the barbell up until you can rest it on your chest. Move the barbell over and slightly behind your head and make sure your arms are fully extended. Keep your head up at all'),
('Overhead_Stretch', 'Overhead Stretch', 'core', ARRAY['chest','arms','back','arms']::text[], 'other', 'stretching', 'beginner', 'Standing straight up, lace your fingers together and open your palms to the ceiling. Keep your shoulders down as you extend your arms up. To create a full torso stretch, pull your tailbone down and stabilize your torso as you do this. Stretch the muscles on both the front and the back of the torso.'),
('Overhead_Triceps', 'Overhead Triceps', 'arms', ARRAY['back']::text[], 'bodyweight', 'stretching', 'expert', 'Sit upright on the floor with your partner behind you. Raise one arm straight up, and flex the elbow, attempting to touch your hand to your back. Your parner should hold your elbow and wrist. This will be your starting position. Attempt to extend the arm straight into the air as your partner prevents you from doing actually doing so. After 10-20 seconds, relax the arm and allow your partner to further stretch the tricep by applying gentle pressure to the wrist. Hold for 10-20 seconds, and then s'),
('Pallof_Press', 'Pallof Press', 'core', ARRAY['chest','shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to a tower, and—if possible—position the cable to shoulder height. If not, a low pulley will suffice. With your side to the cable, grab the handle with both hands and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. With your feet positioned hip-width apart and knees slightly bent, hold the cable to the middle of your chest. This will be your starting position. Press the cable away fro'),
('Pallof_Press_With_Rotation', 'Pallof Press With Rotation', 'core', ARRAY['chest','shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to a tower, and position the cable to shoulder height. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Align outstretched arm with cable. With your feet positioned hip-width apart, pull the cable into your chest and grab the handle with your other hand. Both hands should be on the handle at this time. Facing forward, press'),
('Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'Palms-Down Dumbbell Wrist Curl Over A Bench', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a pronated grip (palms facing down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be'),
('Palms-Down_Wrist_Curl_Over_A_Bench', 'Palms-Down Wrist Curl Over A Bench', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start out by placing a barbell on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab the barbell with a pronated grip (palms down) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be stationary as your w'),
('Palms-Up_Barbell_Wrist_Curl_Over_A_Bench', 'Palms-Up Barbell Wrist Curl Over A Bench', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start out by placing a barbell on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab the barbell with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Your forearms should be stationary as your wr'),
('Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'Palms-Up Dumbbell Wrist Curl Over A Bench', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start out by placing two dumbbells on one side of a flat bench. Kneel down on both of your knees so that your body is facing the flat bench. Use your arms to grab both of the dumbbells with a supinated grip (palms up) and bring them up so that your forearms are resting against the flat bench. Your wrists should be hanging over the edge. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back down to the starting position while inhaling. Make sure to inhale during this'),
('Parallel_Bar_Dip', 'Parallel Bar Dip', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'strength', 'beginner', 'Stand between a set of parallel bars. Place a hand on each bar, and then take a small jump to help you get into the starting position with your arms locked out. Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. Reverse the motion by extending the elbow, pushing yourself back up into the starting position. Repeat for the desired number of repetitions.'),
('Pelvic_Tilt_Into_Bridge', 'Pelvic Tilt Into Bridge', 'back', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie down with your feet on the floor, heels directly under your knees. Lift only your tailbone to the ceiling to stretch your lower back. (Don''t lift the entire spine yet.) Pull in your stomach. To go into a bridge, lift the entire spine except the neck.'),
('Peroneals-SMR', 'Peroneals-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lay on your side, supporting your weight on your forearm and on a foam roller placed on the outside of your lower leg. Your upper leg can either be on top of your lower leg, or you can cross it in front of you. This will be your starting position. Raise your hips off of the ground and begin to roll from below the knee to above the ankle on the side of your leg, pausing at points of tension for 10-30 seconds. Repeat on the other leg.'),
('Peroneals_Stretch', 'Peroneals Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'In a seated position, loop a belt, rope, or band around one foot. This will be your starting position. With the leg extended and the heel off of the ground, pull on the belt so that the foot is inverted, with the inside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.'),
('Physioball_Hip_Bridge', 'Physioball Hip Bridge', 'legs', ARRAY['legs']::text[], 'other', 'strength', 'beginner', 'Lay on a ball so that your upper back is on the ball with your hips unsupported. Both feet should be flat on the floor, hip width apart or wider. This will be your starting position. Begin by extending the hips using your glutes and hamstrings, raising your hips upward as you bridge. Pause at the top of the motion and return to the starting position.'),
('Pin_Presses', 'Pin Presses', 'arms', ARRAY['chest','arms','back','back','shoulders']::text[], 'barbell', 'powerlifting', 'intermediate', 'Pin presses remove the eccentric phase of the bench press, developing starting strength. They also allow you to train a desired range of motion. The bench should be set up in a power rack. Set the pins to the desired point in your range of motion, whether it just be lockout or an inch off of your chest. The bar should be moved to the pins and prepared for lifting. Begin by lying on the bench, with the bar directly above the contact point during your regular bench. Tuck your feet underneath you a'),
('Piriformis-SMR', 'Piriformis-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Sit with your buttocks on top of a foam roll. Bend your knees, and then cross one leg so that the ankle is over the knee. This will be your starting position. Shift your weight to the side of the crossed leg, rolling over the buttocks until you feel tension in your upper glute. You may assist the stretch by using one hand to pull the bent knee towards your chest. Hold this position for 10-30 seconds, and then switch sides.'),
('Plank', 'Plank', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder. Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.'),
('Plate_Pinch', 'Plate Pinch', 'arms', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Grab two wide-rimmed plates and put them together with the smooth sides facing outward Use your fingers to grip the outside part of the plate and your thumb for the other side thus holding both plates together. This is the starting position. Squeeze the plate with your fingers and thumb. Hold this position for as long as you can. Repeat for the recommended amount of sets prescribed in your program. Switch arms and repeat the movements.'),
('Plate_Twist', 'Plate Twist', 'core', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Lie down on the floor or an exercise mat with your legs fully extended and your upper body upright. Grab the plate by its sides with both hands out in front of your abdominals with your arms slightly bent. Slowly cross your legs near your ankles and lift them up off the ground. Your knees should also be bent slightly. Note: Move your upper body back slightly to help keep you balanced turning this exercise. This is the starting position. Move the plate to the left side and touch the floor with it'),
('Platform_Hamstring_Slides', 'Platform Hamstring Slides', 'legs', ARRAY['legs']::text[], 'other', 'strength', 'beginner', 'For this movement a wooden floor or similar is needed. Lay on your back with your legs extended. Place a gym towel or a light weight underneath your heel. This will be your starting position. Begin the movement by flexing the knee, keeping your other leg straight. Continue bringing the heel closer to you, sliding it on the floor. At full knee flexion, reverse the movement to return to the starting position.'),
('Plie_Dumbbell_Squat', 'Plie Dumbbell Squat', 'legs', ARRAY['core','legs','legs','legs']::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell at the base with both hands and stand straight up. Move your legs so that they are wider than shoulder width apart from each other with your knees slightly bent. Your toes should be facing out. Note: Your arms should be stationary while performing the exercise. This is the starting position. Slowly bend the knees and lower your legs until your thighs are parallel to the floor. Make sure to inhale as this is the eccentric part of the exercise. Press mainly with the heel of the foo'),
('Plyo_Kettlebell_Pushups', 'Plyo Kettlebell Pushups', 'chest', ARRAY['shoulders','arms']::text[], 'kettlebell', 'strength', 'expert', 'Place a kettlebell on the floor. Place yourself in a pushup position, on your toes with one hand on the ground and one hand holding the kettlebell, with your elbows extended. This will be your starting position. Begin by lowering yourself as low as you can, keeping your back straight. Quickly and forcefully reverse direction, pushing yourself up to the other side of the kettlebell, switching hands as you do so. Continue the movement by descending and repeating the movement back and forth.'),
('Plyo_Push-up', 'Plyo Push-up', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Move into a prone position on the floor, supporting your weight on your hands and toes. Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position. Descend by flexing at the elbow, lowering your chest towards the ground. At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible. Attempt to push your upper body up until your hands leave the ground. Retur'),
('Posterior_Tibialis_Stretch', 'Posterior Tibialis Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'In a seated position, loop a belt, rope, or band around one foot. This will be your starting position. With the leg extended and the heel off of the ground, pull on the belt so that the foot is everted, with the outside of the foot being pulled towards you. Hold for 10-20 seconds, and then switch sides.'),
('Power_Clean', 'Power Clean', 'legs', ARRAY['legs','arms','legs','back','back','legs','shoulders','back','arms']::text[], 'barbell', 'strength', 'intermediate', 'Stand with your feet slightly wider than shoulder width apart and toes pointing out slightly. Squat down and grasp bar with a closed, pronated grip. Your hands should be slightly wider than shoulder width apart outside knees with elbows fully extended. Place the bar about 1 inch in front of your shins and over the balls of your feet. Your back should be flat or slightly arched, your chest held up and out and your shoulder blades should be retracted. Keep your head in a neutral position (in line '),
('Power_Clean_from_Blocks', 'Power Clean from Blocks', 'legs', ARRAY['legs']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on boxes of the desired height, take a grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. As the bar approaches the mid-thigh position, begin extending through the hips. In a j'),
('Power_Jerk', 'Power Jerk', 'legs', ARRAY['core','legs','legs','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as'),
('Power_Partials', 'Power Partials', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. Your feet should be about shoulder width apart. This will be your starting position. Keeping your arms straight and the torso stationary, lift the weights out to your sides until they are about shoulder level height while exhaling. Feel the contraction for a second and begin to lower the weights back down to the start')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Power_Snatch', 'Power Snatch', 'legs', ARRAY['legs','legs','back','legs','shoulders','back','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same u'),
('Power_Snatch_from_Blocks', 'Power Snatch from Blocks', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position. Begin the first pull by driving through the front of the heels, raising the bar from the boxes. Transition into the second pull by '),
('Power_Stairs', 'Power Stairs', 'legs', ARRAY['legs','legs','legs','back','legs','shoulders','back']::text[], 'other', 'strongman', 'intermediate', 'In the power stairs, implements are moved up a staircase. For training purposes, these can be performed with a tire or box. Begin by taking the implement with both hands. Set your feet wide, with your head and chest up. Drive through the ground with your heels, extending your knees and hips to raise the weight from the ground. As you lean back, attempt to swing the weight onto the stairs, which are usually around 16-18" high. You can use your legs to help push the weight onto the stair. Repeat f'),
('Preacher_Curl', 'Preacher Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder leng'),
('Preacher_Hammer_Dumbbell_Curl', 'Preacher Hammer Dumbbell Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Place the upper part of both arms on top of the preacher bench as you hold a dumbbell in each hand with the palms facing each other (neutral grip). As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbells are at shoulder height. Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of r'),
('Press_Sit-Up', 'Press Sit-Up', 'core', ARRAY['chest','shoulders','arms']::text[], 'barbell', 'strength', 'expert', 'To begin, lie down on a bench with a barbell resting on your chest. Position your legs so they are secure on the extension of the abdominal bench. This is the starting position. While inhaling, tighten your abdominals and glutes. Simultaneously curl your torso as you do when performing a sit-up and press the barbell to an overhead position while exhaling. Tip: Use your arms to push the barbell out as you perform this exercise while still focusing on the abdominal muscles. Lower your upper body b'),
('Prone_Manual_Hamstring', 'Prone Manual Hamstring', 'legs', ARRAY[]::text[], 'other', 'strength', 'beginner', 'You will need a partner for this exercise. Lay face down with your legs straight. Your assistant will place their hand on your heel. To begin, flex the knee to curl your leg up. Your partner should provide resistance, starting light and increasing the pressure as the movement is completed. Communicate with your partner to monitor appropriate resistance levels. Pause at the top, returning the leg to the starting position as your partner provides resistance going the other direction.'),
('Prowler_Sprint', 'Prowler Sprint', 'legs', ARRAY['legs','chest','legs','legs','shoulders']::text[], 'other', 'cardio', 'beginner', 'Place your sled on an appropriate surface, loaded to a suitable weight. The sled should provide enough resistance to require effort, but not so heavy that you are significantly slowed down. You may use the upright or the low handles for this exercise. Place your hands on the handles with your arms extended, leaning into the implement. With good posture, drive through the ground with alternating, short steps. Move as fast as you can for a short distance.'),
('Pull_Through', 'Pull Through', 'legs', ARRAY['legs','back']::text[], 'cable', 'strength', 'beginner', 'Begin standing a few feet in front of a low pulley with a rope or handle attached. Face away from the machine, straddling the cable, with your feet set wide apart. Begin the movement by reaching through your legs as far as possible, bending at the hips. Keep your knees slightly bent. Keeping your arms straight, extend through the hip to stand straight up. Avoid pulling upward through the shoulders; all of the motion should originate through the hips.'),
('Pullups', 'Pullups', 'back', ARRAY['arms','back']::text[], 'bodyweight', 'strength', 'beginner', 'Grab the pull-up bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creati'),
('Push-Up_Wide', 'Push-Up Wide', 'chest', ARRAY['core','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position. To begin, allow the elbows to flex, lowering your chest to the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step. After pausing at the contracted position, repeat the movement'),
('Push-Ups_-_Close_Triceps_Position', 'Push-Ups - Close Triceps Position', 'arms', ARRAY['chest','shoulders']::text[], 'bodyweight', 'strength', 'intermediate', 'Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms'' length. Lower yourself until your chest almost touches the floor as you inhale. Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step. After a second pause at the contracted position, repeat the movement for the prescribed amou'),
('Push-Ups_With_Feet_Elevated', 'Push-Ups With Feet Elevated', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length. Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is. Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you'),
('Push-Ups_With_Feet_On_An_Exercise_Ball', 'Push-Ups With Feet On An Exercise Ball', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'strength', 'intermediate', 'Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length. Place your toes on top of an exercise ball. This will allow your body to be elevated. Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step. After a second pause at the contracted position, repeat the movement for'),
('Push_Press', 'Push Press', 'shoulders', ARRAY['legs','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', NULL),
('Push_Press_-_Behind_the_Neck', 'Push Press - Behind the Neck', 'shoulders', ARRAY['legs','legs','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Standing with the weight racked on the back of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, moving the bar in a vertical path. Using the momentum generated, finish pressing the weight overhead be extending through the arms. Return to the starting position, using your legs to abso'),
('Push_Up_to_Side_Plank', 'Push Up to Side Plank', 'chest', ARRAY['core','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Get into pushup position on the toes with your hands just outside of shoulder width. Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight. Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank. Lower the arm back to the floor for another pushup and then twist to the other side. Repeat the series, alternating each side, for 10 or more reps.'),
('Pushups', 'Pushups', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Next, lower yourself downward until your chest almost touches the floor as you inhale. Now breathe out and press your upper body back up to the starting position while squeezing your chest. After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.'),
('Pushups_Close_and_Wide_Hand_Positions', 'Pushups (Close and Wide Hand Positions)', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length. Lower yourself until your chest almost touches the floor as you inhale. Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step. After a second pause at the co'),
('Pyramid', 'Pyramid', 'back', ARRAY['shoulders']::text[], 'other', 'stretching', 'beginner', 'Start off by rolling your torso forward onto the ball so your hips rest on top of the ball and become the highest point of your body. Rest your hands and feet on the floor. Your arms and legs can be slightly bent or straight, depending on the size of the ball, your flexibility, and the length of your limbs. This also helps develop stabilizing strength in your torso and shoulders.'),
('Quad_Stretch', 'Quad Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lay on your side. Loop a belt, rope, or band around your top foot. Flex the knee and extend your hip, attempting to touch your glutes with your foot, and holding the belt with your hands. This will be your starting position. With the belt being held over the shoulder or overhead, gently pull to increase the stretch in the quadriceps. Hold for 10-20 seconds, and then switch sides.'),
('Quadriceps-SMR', 'Quadriceps-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lay facedown on the floor with your weight supported by your hands or forearms. Place a foam roll underneath one leg on the quadriceps, and keep the foot off of the ground. Make sure to relax the leg as much as possible. This will be your starting position. Shifting as much weight onto the leg to be stretched as is tolerable, roll over the foam from above the knee to below the hip, holding points of tension for 10-30 seconds. Switch sides.'),
('Quick_Leap', 'Quick Leap', 'legs', ARRAY['legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'You will need a box for this exerise. Begin facing the box standing 1-2 feet from its edge. By utilizing your hips, hop onto the box, landing on both legs. Ensure that you land with your legs bent and your feet flat. Immediately upon landing, fully extend through the entire body and swing your arms overhead to explode off of the box. Use your legs to absorb the impact of landing.'),
('Rack_Delivery', 'Rack Delivery', 'shoulders', ARRAY['arms','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'This drill teaches the delivery of the barbell to the rack position on the shoulders. Begin holding a bar in the scarecrow position, with the upper arms parallel to the floor, and the forearms hanging down. Use a hook grip, with your fingers wrapped over your thumbs. Begin by rotating the elbows around the bar, delivering the bar to the shoulders. As your elbows come forward, relax your grip. The shoulders should be protracted, providing a shelf for the bar, which should lightly contact the thro'),
('Rack_Pull_with_Bands', 'Rack Pull with Bands', 'back', ARRAY['arms','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Attach bands to the base of the rack, or secure them with dumbbells. Attach the other end to the bar. You may need to choke the bands to provide tension. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since '),
('Rack_Pulls', 'Rack Pulls', 'back', ARRAY['arms','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Set up in a power rack with the bar on the pins. The pins should be set to the desired point; just below the knees, just above, or in the mid thigh position. Position yourself against the bar in proper deadlifting position. Your feet should be under your hips, your grip shoulder width, back arched, and hips back to engage the hamstrings. Since the weight is typically heavy, you may use a mixed grip, a hook grip, or use straps to aid in holding the weight. With your head looking forward, extend t'),
('Rear_Leg_Raises', 'Rear Leg Raises', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position. Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides.'),
('Recumbent_Bike', 'Recumbent Bike', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'beginner', 'To begin, seat yourself on the bike and adjust the seat to your height. Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity. Recumbent'),
('Return_Push_from_Stance', 'Return Push from Stance', 'shoulders', ARRAY['chest','arms']::text[], 'other', 'plyometrics', 'beginner', 'You will need a partner for this drill. Begin in an athletic 2 or 3 point stance. At the signal, move into a position to receive the pass from your partner. Catch the medicine ball with both hands and immediately throw it back to your partner. You can modify this drill by running different routes.'),
('Reverse_Band_Bench_Press', 'Reverse Band Bench Press', 'arms', ARRAY['chest','arms','back','back','shoulders']::text[], 'barbell', 'powerlifting', 'intermediate', 'Position a bench inside a power rack, with the bar set to the correct height. Begin by anchoring bands either to band pegs or to the top of the rack. Ensure that you will be position properly under the bands. Attach the other end to the barbell. Lie on the bench, tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Ma'),
('Reverse_Band_Box_Squat', 'Reverse Band Box Squat', 'legs', ARRAY['legs','legs','legs','arms','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin in a power rack with a box at the appropriate height behind you. Set up the bands either on band pegs or attached to the top of the rack, ensuring they will be directly above the bar during the squat. Attach the other end to the bar. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your'),
('Reverse_Band_Deadlift', 'Reverse Band Deadlift', 'back', ARRAY['legs','legs','legs','legs','legs','legs']::text[], 'barbell', 'powerlifting', 'expert', 'Set the bar up in a power rack. Attach bands to the top of the rack, using either bands pegs or the frame itself. Attach the other end of the bands to the bar. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower'),
('Reverse_Band_Power_Squat', 'Reverse Band Power Squat', 'legs', ARRAY['legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'expert', 'Begin in a power rack with the pins and bar set at the appropriate height. After loading the bar, attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end of the bands to the bar. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and ste'),
('Reverse_Band_Sumo_Deadlift', 'Reverse Band Sumo Deadlift', 'legs', ARRAY['legs','legs','legs','arms','legs','back','legs','back']::text[], 'barbell', 'powerlifting', 'expert', 'Begin with a bar loaded on the floor inside of a power rack. Attach bands to the top of the rack, using either pegs or the frame itself. Attach the other end to the barbell. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthen'),
('Reverse_Barbell_Curl', 'Reverse Barbell Curl', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze '),
('Reverse_Barbell_Preacher_Curls', 'Reverse Barbell Preacher Curls', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'intermediate', 'Grab an EZ-bar using a shoulder width and palms down (pronated) grip. Now place the upper part of both arms on top of the preacher bench and have your arms extended. This will be your starting position. As you exhale, use the biceps to curl the weight up until your biceps are fully contracted and the barbell is at shoulder height. Squeeze the biceps hard for a second at the contracted position. As you breathe in, slowly lower the barbell until your upper arms are extended and the biceps is fully'),
('Reverse_Cable_Curl', 'Reverse Cable Curl', 'arms', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracte'),
('Reverse_Crunch', 'Reverse Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise. Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position. While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching y'),
('Reverse_Flyes', 'Reverse Flyes', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'To begin, lie down on an incline bench with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing each other (neutral grip). Extend the arms in front of you so that they are perpendicular to the angle of the bench. The legs should be stationary while applying pressure with the ball of your toes. This is the starting position. Maintaining the slight bend of the elbows, move the weights out and away from each other (to the side) in an arc motion '),
('Reverse_Flyes_With_External_Rotation', 'Reverse Flyes With External Rotation', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'To begin, lie down on an incline bench set at a 30-degree angle with the chest and stomach pressing against the incline. Have the dumbbells in each hand with the palms facing down to the floor. Your arms should be in front of you so that they are perpendicular to the angle of the bench. Tip: Your elbows should have a slight bend. The legs should be stationary while applying pressure with the ball of your toes (your heels should not be touching the floor). This is the starting position. Maintaini'),
('Reverse_Grip_Bent-Over_Rows', 'Reverse Grip Bent-Over Rows', 'back', ARRAY['arms','back','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'Stand erect while holding a barbell with a supinated grip (palms facing up). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. While keeping the torso stationary, lift the barbell as you breathe out, keeping the '),
('Reverse_Grip_Triceps_Pushdown', 'Reverse Grip Triceps Pushdown', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Start by setting a bar attachment (straight or e-z) on a high pulley machine. Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position. Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should m'),
('Reverse_Hyperextension', 'Reverse Hyperextension', 'legs', ARRAY['legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Place your feet between the pads after loading an appropriate weight. Lay on the top pad, allowing your hips to hang off the back, while grasping the handles to hold your position. To begin the movement, flex the hips, pulling the legs forward. Reverse the motion by extending the hips, kicking the leg back. It is very important not to over-extend the hip on this movement, stopping short of your full range of motion. Return by again flexing the hip, pulling the carriage forward as far as you can.'),
('Reverse_Machine_Flyes', 'Reverse Machine Flyes', 'shoulders', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position. In a semicircular motion, pull your hands out to your side and back, contracting your rear delts. Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint. Pause at the rear of the movement, and slowly re'),
('Reverse_Plate_Curls', 'Reverse Plate Curls', 'arms', ARRAY['arms']::text[], 'other', 'strength', 'beginner', 'Start by standing straight with a weighted plate held by both hands and arms fully extended. Use a pronated grip (palms facing down) and make sure your fingers grab the rough side of the plate while your thumb grabs the smooth side. Note: For the best results, grab the weighted plate at an 11:00 and 1:00 o''clock position. Your feet should be shoulder width apart from each other and the weighted plate should be near the groin area. This is the starting position. Slowly lift the plate up while ke'),
('Reverse_Triceps_Bench_Press', 'Reverse Triceps Bench Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'Lie back on a flat bench. Using a close, supinated grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked extended in front of you and perpendicular to the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement. After a second'),
('Rhomboids-SMR', 'Rhomboids-SMR', 'back', ARRAY['back']::text[], 'other', 'stretching', 'intermediate', 'Lay down with your back on the floor. Place a foam roll underneath your upper back, and cross your arms in front of you, protracting your shoulders. This will be your starting position. Raise your hips off of the ground, placing your weight onto the foam roll. Shift your weight to one side at a time, rolling over your middle and upper back. Pause at points of tension for 10-30 seconds.'),
('Rickshaw_Carry', 'Rickshaw Carry', 'arms', ARRAY['core','legs','legs','legs','back','legs','back']::text[], 'other', 'strongman', 'intermediate', 'Position the frame at the starting point, and load with the appropriate weight. Standing in the center of the frame, begin by gripping the handles and driving through your heels to lift the frame. Ensure your chest and head are up and your back is straight. Immediately begin walking briskly with quick, controlled steps. Keep your chest up and head forward, and make sure you continue breathing. Bring the frame to the ground after you have reached the end point.'),
('Rickshaw_Deadlift', 'Rickshaw Deadlift', 'legs', ARRAY['arms','legs','legs','back','back']::text[], 'other', 'strongman', 'intermediate', 'Load the frame with the desired weight. Center yourself between the handles. You feet should be about hip width apart. Bend at the hips to grip the handles, allowing your shoulder blades to protract. With your feet and your grip set, take a big breath and then lower your hips and flex the knees. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you driv'),
('Ring_Dips', 'Ring Dips', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'strength', 'intermediate', 'Grip a ring in each hand, and then take a small jump to help you get into the starting position with your arms locked out. Begin by flexing the elbow, lowering your body until your arms break 90 degrees. Avoid swinging, and maintain good posture throughout the descent. Reverse the motion by extending the elbow, pushing yourself back up into the starting position. Repeat for the desired number of repetitions.')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Rocket_Jump', 'Rocket Jump', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body. To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, reaching overhead as far as possible. As you land, absorb your impact through the legs.'),
('Rocking_Standing_Calf_Raise', 'Rocking Standing Calf Raise', 'legs', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place it on the back of your shoulders (slightly below the neck). Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoul'),
('Rocky_Pull-Ups_Pulldowns', 'Rocky Pull-Ups/Pulldowns', 'back', ARRAY['arms','back','shoulders']::text[], 'other', 'strength', 'intermediate', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. Pull your torso up until the bar touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of the movement. Tip: Concentrate on'),
('Romanian_Deadlift', 'Romanian Deadlift', 'legs', ARRAY['legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion. Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position. Keeping your back and arms completely straight at all times, use your hips to lift th'),
('Romanian_Deadlift_from_Deficit', 'Romanian Deadlift from Deficit', 'legs', ARRAY['arms','legs','back','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin standing while holding a bar at arm''s length in front of you. You can stand on a raised platform to increase the range of motion. Begin by flexing the knees slightly, and then flex at the hip, moving your butt back as far as possible, lowering the torso as far as flexibility allows. The back should remain in absolute extension at all times, and the bar should remain in contact with the legs. If done properly, there should be heavy tension felt in the hamstrings. Reverse the motion to retu'),
('Rope_Climb', 'Rope Climb', 'back', ARRAY['arms','arms','back','shoulders']::text[], 'other', 'strength', 'intermediate', 'Grab the rope with both hands above your head. Pull down on the rope as you take a small jump. Wrap the rope around one leg, using your feet to pinch the rope. Reach up as high as possible with your arms, gripping the rope tightly. Release the rope from your feet as you pull yourself up with your arms, bringing your knees towards your chest. Resecure your feet on the rope, and then stand up to take another high hold on the rope. Continue until you reach the top of the rope. To lower yourself, lo'),
('Rope_Crunch', 'Rope Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Kneel 1-2 feet in front of a cable system with a rope attached. After selecting an appropriate weight, grasp the rope with both hands reaching overhead. Your torso should be upright in the starting position. To begin, flex at the spine, attempting to bring your rib cage to your legs as you pull the cable down. Pause at the bottom of the motion, and then slowly return to the starting position. These can be done with twists or to the side to hit the obliques.'),
('Rope_Jumping', 'Rope Jumping', 'legs', ARRAY['legs','legs']::text[], 'other', 'cardio', 'intermediate', 'Hold an end of the rope in each hand. Position the rope behind you on the ground. Raise your arms up and turn the rope over your head bringing it down in front of you. When it reaches the ground, jump over it. Find a good turning pace that can be maintained. Different speeds and techniques can be used to introduce variation. Rope jumping is exciting, challenges your coordination, and requires a lot of energy. A 150 lb person will burn about 350 calories jumping rope for 30 minutes, compared to o'),
('Rope_Straight-Arm_Pulldown', 'Rope Straight-Arm Pulldown', 'back', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position. Keeping your arms straight, extend the shoulder to pull the rope down to your thighs. Pause at the bottom of the motion, squeezing your lats. Return to the starting position without allowing the weigh'),
('Round_The_World_Shoulder_Stretch', 'Round The World Shoulder Stretch', 'shoulders', ARRAY['arms','chest']::text[], 'other', 'stretching', 'beginner', 'Stand up straight with your legs together, holding a bodybar or broomstick. Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out. Slowly lift your arms up behind your head. Don''t force it if it gets hard to lift further.'),
('Rowing_Stationary', 'Rowing, Stationary', 'legs', ARRAY['arms','legs','legs','legs','back','back']::text[], 'machine', 'cardio', 'intermediate', 'To begin, seat yourself on the rower. Make sure that your heels are resting comfortably against the base of the foot pedals and that the straps are secured. Select the program that you wish to use, if applicable. Sit up straight and bend forward at the hips. There are three phases of movement when using a rower. The first phase is when you come forward on the rower. Your knees are bent and against your chest. Your upper body is leaning slightly forward while still maintaining good posture. Next,'),
('Runners_Stretch', 'Runner''s Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'It''s easiest to get into this stretch if you start standing up, put one leg behind you, and slowly lower your torso down to the floor. Keep the front heel on the floor (if it lifts up, scoot your other leg further back). Place your hands on either side of your front leg. To get more out of this stretch, push your butt up toward the ceiling, and then gradually lower it back toward the floor. You''ll Stretch the hip flexor of the back leg and the hamstring and buttocks of the front.'),
('Running_Treadmill', 'Running, Treadmill', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'beginner', 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than running outside. A 150 lb person will burn over 450 calories running 8 miles per hour f'),
('Russian_Twist', 'Russian Twist', 'core', ARRAY['back']::text[], 'bodyweight', 'strength', 'intermediate', 'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees. Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position. Twist your torso to the right side until your arms are parallel with the floor while breathing out. Hold the contraction for '),
('Sandbag_Load', 'Sandbag Load', 'legs', ARRAY['core','arms','legs','arms','legs','legs','back','back','shoulders','back']::text[], 'other', 'strongman', 'beginner', 'To load sandbags or other objects, begin with the implements placed a distance from the loading platform, typically 50 feet. Begin by lifting the sandbag. Sandbags are extremely awkward, and the manner of lifting them can vary depending on the particular sandbag used. Reach as far around it as possible, extending through the hips and knees to pull it up high. Shouldering is usually not allowed. Move as quickly as possible to the platform, and load it, extending through your hips, knees, and ankl'),
('Scapular_Pull-Up', 'Scapular Pull-Up', 'back', ARRAY['back','back']::text[], 'other', 'strength', 'beginner', 'Take a pronated grip on a pull-up bar. From a hanging position, raise yourself a few inches without using your arms. Do this by depressing your shoulder girdle in a reverse shrugging motion. Pause at the completion of the movement, and then slowly return to the starting position before performing more repetitions.'),
('Scissor_Kick', 'Scissor Kick', 'core', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'To begin, lie down with your back pressed against the floor or on an exercise mat (optional). Your arms should be fully extended to the sides with your palms facing down. Note: The arms should be stationary the entire time. With a slight bend at the knees, lift your legs up so that your heels are about 6 inches off the ground. This is the starting position. Now lift your left leg up to about a 45 degree angle while your right leg is lowered until the heel is about 2-3 inches from the ground. Swi'),
('Scissors_Jump', 'Scissors Jump', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground. Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift. As you jump as high as you can, switch the position of your legs, moving your front leg to the back and the rear leg to the front. As you land, absorb the impact through the legs by adopting the lunge position, and repeat.'),
('Seated_Band_Hamstring_Curl', 'Seated Band Hamstring Curl', 'legs', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Secure a band close to the ground and place a bench a couple feet away from it. Seat yourself on the bench and secure the band behind your ankles, beginning with your legs straight. This will be your starting position. Flex the knees, bringing your feet towards the bench. You may need to lean back slightly to keep your feet from striking the floor. Pause at the completion of the movement, and then slowly return to the starting position.'),
('Seated_Barbell_Military_Press', 'Seated Barbell Military Press', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'intermediate', 'Sit on a Military Press Bench with a bar behind your head and either have a spotter give you the bar (better on the rotator cuff this way) or pick it up yourself carefully with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. Once you pick up the barbell with the correct grip length, lift the bar up over your head by locking your arms. Hold at about sho'),
('Seated_Barbell_Twist', 'Seated Barbell Twist', 'core', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start out by sitting at the end of a flat bench with a barbell placed on top of your thighs. Your feet should be shoulder width apart from each other. Grip the bar with your palms facing down and make sure your hands are wider than shoulder width apart from each other. Begin to lift the barbell up over your head until your arms are fully extended. Now lower the barbell behind your head until it is resting along the base of your neck. This is the starting position. While keeping your feet and hea'),
('Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'Seated Bent-Over One-Arm Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit down at the end of a flat bench with a dumbbell in one arm using a neutral grip (palms of the hand facing you). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arm with the dumbbell should be close to the torso and aligned with it (lifted up until it is parallel to the floor while the forearms are pointing towards the floor as the hands hold'),
('Seated_Bent-Over_Rear_Delt_Raise', 'Seated Bent-Over Rear Delt Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Place a couple of dumbbells looking forward in front of a flat bench. Sit on the end of the bench with your legs together and the dumbbells behind your calves. Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position. Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are par'),
('Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'Seated Bent-Over Two-Arm Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Sit down at the end of a flat bench with a dumbbell in both arms using a neutral grip (palms of the hand facing you). Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms with the dumbbells should be close to the torso and aligned with it (lifted up until they are parallel to the floor while the forearms are pointing towards the floor as the han'),
('Seated_Biceps', 'Seated Biceps', 'arms', ARRAY['chest','shoulders']::text[], 'bodyweight', 'stretching', 'expert', 'Sit on the floor with your knees bent and your partner standing behind you. Extend your arms straight behind you with your palms facing each other. Your partner will hold your wrists for you. This will be the starting position. Attempt to flex your elbows, while your partner prevents any actual movement. After 10-20 seconds, relax your arms while your partner gently pulls your wrists up to stretch your biceps. Be sure to let your partner know when the stretch is appropriate to prevent injury or '),
('Seated_Cable_Rows', 'Seated Cable Rows', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'beginner', 'For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the V-bar handles. With your arms extended pull back until yo'),
('Seated_Cable_Shoulder_Press', 'Seated Cable Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 90 degrees to the body, with your head and chest up. The elbows should also be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together above your head. After pausing at the top, return the handles to the starting position. Ensure that you maintain tension on the cables. You can also execute this movement with yo'),
('Seated_Calf_Raise', 'Seated Calf Raise', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Sit on the machine and place your toes on the lower portion of the platform provided with the heels extending off. Choose the toe positioning of your choice (forward, in, or out) as per the beginning of this chapter. Place your lower thighs under the lever pad, which will need to be adjusted according to the height of your thighs. Now place your hands on top of the lever pad in order to prevent it from slipping forward. Lift the lever slightly by pushing your heels up and release the safety bar.'),
('Seated_Calf_Stretch', 'Seated Calf Stretch', 'legs', ARRAY['legs','back']::text[], 'other', 'stretching', 'beginner', 'Sit up straight on an exercise mat. Bend one knee and put that foot on the floor to stabilize the torso. Straighten your other leg and flex your ankle. Using a band, towel, or your hand if you can reach, pull the toes toward you. Hold for 10 to 20 seconds, then switch sides.'),
('Seated_Close-Grip_Concentration_Barbell_Curl', 'Seated Close-Grip Concentration Barbell Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'Sit down on a flat bench with a barbell or E-Z Bar in front of you in between your legs. Your legs should be spread with the knees bent and the feet on the floor. Use your arms to pick the barbell up and place the back of your upper arms on top of your inner thighs (around three and a half inches away from the front of the knee). A supinated grip closer than shoulder width is needed to perform this exercise. Tip: Your arm should be extended at arms length and the barbell should be above the floo'),
('Seated_Dumbbell_Curl', 'Seated Dumbbell Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit on a flat bench with a dumbbell on each hand being held at arms length. The elbows should be close to the torso. Rotate the palms of the hands so that they are facing your torso. This will be your starting position. While holding the upper arm stationary, curl the weights and start twisting the wrists once the dumbbells pass your thighs so that the palms of your hands face forward at the end of the movement. Make sure that you contract the biceps as you breathe out and make sure that only th'),
('Seated_Dumbbell_Inner_Biceps_Curl', 'Seated Dumbbell Inner Biceps Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit on the end of a flat bench with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the dumbbells out and up, turning the palms out as you lift and keeping your forearms in line with your outer deltoids. Tips: Only the forearms should move. Continue the movement until your biceps are full'),
('Seated_Dumbbell_Palms-Down_Wrist_Curl', 'Seated Dumbbell Palms-Down Wrist Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing down. Your wrists should be hanging over the edge of your thighs. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists bac'),
('Seated_Dumbbell_Palms-Up_Wrist_Curl', 'Seated Dumbbell Palms-Up Wrist Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start out by placing two dumbbells on the floor in front of a flat bench. Sit down on the edge of the flat bench with your legs at about shoulder width apart. Make sure to keep your feet on the floor. Use your arms to grab both of the dumbbells and bring them up so that your forearms are resting against your thighs with the palms of the hands facing up. Your wrists should be hanging over the edge of your thighs. Start out by curling your wrist upwards and exhaling. Slowly lower your wrists back '),
('Seated_Dumbbell_Press', 'Seated Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Grab a couple of dumbbells and sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs. Clean the dumbbells up one at a time by using your thighs to bring the dumbbells up to shoulder height at each side. Rotate the wrists so that the palms of your hands are facing forward. This is your starting position. As you exhale, push the dumbbells up until they touch at the top. After a second pause, slowly come down back to '),
('Seated_Flat_Bench_Leg_Pull-In', 'Seated Flat Bench Leg Pull-In', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position. Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the starting position as you inhale. Repeat for the recommended amount of repetitions.'),
('Seated_Floor_Hamstring_Stretch', 'Seated Floor Hamstring Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Sit on a mat with your right leg extended in front of you and your left leg bent with your foot against your right inner thigh. Lean forward from your hips and reach for your ankle until you feel a stretch in your hamstring. Hold for 15 seconds, then repeat for your other side.'),
('Seated_Front_Deltoid', 'Seated Front Deltoid', 'shoulders', ARRAY['chest']::text[], 'bodyweight', 'stretching', 'expert', 'Sit upright on the floor with your legs bent, your partner standing behind you. Stick your arms straight out to your sides, with your palms facing the ground. Attempt to move them as far behind you as possible, as your assistant holds your wrists. This will be your starting position. Keeping your elbows straight, attempt to move your arms to the front, with your partner gently restraining you to prevent any actual movement for 10-20 seconds. Now, relax your muscles and allow your partner to gent'),
('Seated_Glute', 'Seated Glute', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'expert', 'In a seated position with your knees bent, cross one ankle over the opposite knee. Your partner will stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position. Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso. Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.'),
('Seated_Good_Mornings', 'Seated Good Mornings', 'back', ARRAY['legs']::text[], 'barbell', 'powerlifting', 'intermediate', 'Set up a box in a power rack. The pins should be set at an appropriate height. Begin by stepping under the bar and placing it across the back of the shoulders, not on top of your traps. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back. Keep your head facing forward. With your back, shoulders, and core tight, push your knees and butt out and you begin your '),
('Seated_Hamstring', 'Seated Hamstring', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'expert', 'In a seated position with your legs extended, have your partner stand behind you. Now, lean forward as your partner braces your shoulders with their hands. This will be your starting position. Attempt to push your torso back for 10-20 seconds, as your partner prevents any actual movement of your torso. Now relax your muscles as your partner increases the stretch by gently pushing your torso forward for 10-20 seconds.'),
('Seated_Hamstring_and_Calf_Stretch', 'Seated Hamstring and Calf Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'intermediate', 'Loop a belt, rope, or band around one foot. Sit down with both legs extended . This will be your starting position. Leaning forward slightly, pull on the belt to draw the toes of your foot back. Hold this position for 10-20 seconds and then repeat with the other leg.'),
('Seated_Head_Harness_Neck_Resistance', 'Seated Head Harness Neck Resistance', 'other', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Place a neck strap on the floor at the end of a flat bench. Once you have selected the weights, sit at the end of the flat bench with your feet wider than shoulder width apart from each other. Your toes should be pointed out. Slowly move your torso forward until it is almost parallel with the floor. Using both hands, securely position the neck strap around your head. Tip: Make sure the weights are still lying on the floor to prevent any strain on the neck. Now grab the weight with both hands whi'),
('Seated_Leg_Curl', 'Seated Leg Curl', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad. Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position. As y'),
('Seated_Leg_Tucks', 'Seated Leg Tucks', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position. Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement. After a second pause, go back to the starting position as you inhale. Repeat for the recommended amount of repetitions.'),
('Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl', 'Seated One-Arm Dumbbell Palms-Down Wrist Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm down. Tip: Make sure that the back of the wrist lies on top of your knees. This will be your starting position. Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement. Now curl the dumbbell as h'),
('Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl', 'Seated One-Arm Dumbbell Palms-Up Wrist Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit on a flat bench with a dumbbell in your right hand. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your right forearm on top of your upper right thigh with your palm up. Tip: Make sure that the front of the wrist lies on top of your knees. This will be your starting position. Lower the dumbbell as far as possible as you keep a tight grip on the dumbbell. Inhale as you perform this movement. Now curl the dumbbell as hi'),
('Seated_One-arm_Cable_Pulley_Rows', 'Seated One-arm Cable Pulley Rows', 'back', ARRAY['arms','back','back']::text[], 'cable', 'strength', 'intermediate', 'To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the single handle attachment with your left arm using a palms-down grip. With your arm extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You sh'),
('Seated_Overhead_Stretch', 'Seated Overhead Stretch', 'core', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Sit up straight on an exercise mat. Touch the soles of your feet together with your feet six to eight inches in front of your hips. Place one hand on the floor beside you and your other hand behind your head. Lift your elbow to the ceiling as you incline your torso to the other side. Hold for 10 to 20 seconds, then switch sides.'),
('Seated_Palm-Up_Barbell_Wrist_Curl', 'Seated Palm-Up Barbell Wrist Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms up. Tip: Make sure that the front of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible while inhaling and keeping a tight grip. Now curl bar up as high as possible while f')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Seated_Palms-Down_Barbell_Wrist_Curl', 'Seated Palms-Down Barbell Wrist Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. Lean forward and place your forearms on top of your upper thighs with your palms down. Tip: Make sure that the back of the wrists lay on top of your knees. This will be your starting position. Lower the bar as far as possible while inhaling and keeping a tight grip. Now curl bar up as high as possible whil'),
('Seated_Side_Lateral_Raise', 'Seated Side Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Pick a couple of dumbbells and sit at the end of a flat bench with your feet firmly on the floor. Hold the dumbbells with your palms facing in and your arms straight down at your sides at arms'' length. This will be your starting position. While maintaining the torso stationary (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as yo'),
('Seated_Triceps_Press', 'Seated Triceps Press', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit down on a bench with back support and grasp a dumbbell with both hands and hold it overhead at arm''s length. Tip: a better way is to have somebody hand it to you especially if it is very heavy. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hand should be facing inward. This will be your starting position. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semi-circular mot'),
('Seated_Two-Arm_Palms-Up_Low-Pulley_Wrist_Curl', 'Seated Two-Arm Palms-Up Low-Pulley Wrist Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Put a bench in front of a low pulley machine that has a barbell or EZ Curl attachment on it. Move the bench far enough away so that when you bring the handle to the top of your thighs tension is created on the cable due to the weight stack being moved up. Now hold the handle with both hands, palms up, using a shoulder-width grip. Step back and sit on the bench with your feet about shoulder width apart, firmly on the floor. Lean forward and place the forearms on your thighs with the back of your '),
('See-Saw_Press_Alternating_Side_Press', 'See-Saw Press (Alternating Side Press)', 'shoulders', ARRAY['core','arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Grab a dumbbell with each hand and stand up erect. Clean (lift) the dumbbells to the chest/shoulder level and then rotate your wrists so that your palms are facing towards you as if you were getting ready to perform an Arnold Press. This will be your starting position. Now start extending your left arm overhead as you rotate the wrist so that the palm of your hand faces forward as you go up. Your elbows should come out also as you lift the weight. Simultaneously, you will also be bending from yo'),
('Shotgun_Row', 'Shotgun Row', 'back', ARRAY['arms','back']::text[], 'cable', 'strength', 'beginner', 'Attach a single handle to a low cable. After selecting the correct weight, stand a couple feet back with a wide-split stance. Your arm should be extended and your shoulder forward. This will be your starting position. Perform the movement by retracting the shoulder and flexing the elbow. As you pull, supinate the wrist, turning the palm upward as you go. After a brief pause, return to the starting position.'),
('Shoulder_Circles', 'Shoulder Circles', 'shoulders', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'With shoulders relaxed and arms resting loosely at your sides (or in your lap if you''re seated), gently roll your shoulders forward, up, back, and down. Reverse direction. You can do this exercise alternating shoulders or both at the same time.'),
('Shoulder_Press_-_With_Bands', 'Shoulder Press - With Bands', 'shoulders', ARRAY['arms']::text[], 'bands', 'strength', 'beginner', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles and lift them so that the hands are at shoulder height at each side. Rotate the wrists so that the palms of your hands are facing forward. Your elbows should be bent, with the upper arms and forearms in line to the torso. This is your starting position. As you exhale, lift the handles up until your arms are fully extended overhead.'),
('Shoulder_Raise', 'Shoulder Raise', 'shoulders', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Relax your arms to your sides and raise your shoulders up toward your ears, then back down.'),
('Shoulder_Stretch', 'Shoulder Stretch', 'shoulders', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Reach your left arm across your body and hold it straight.'),
('Side-Lying_Floor_Stretch', 'Side-Lying Floor Stretch', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'First lie on your left side, bending your left knee in front of you to stabilize your torso (use your abdominal muscles as well to hold you upright). Straighten your right leg and rest the right foot on the floor behind your left. Straighten your right arm over your head and gently pull on your right wrist to stretch the entire right side of the body. Switch sides.'),
('Side_Bridge', 'Side Bridge', 'core', ARRAY['shoulders']::text[], 'bodyweight', 'strength', 'beginner', NULL),
('Side_Hop-Sprint', 'Side Hop-Sprint', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to the side of a cone or hurdle. Begin this drill by hopping sideways over the obstacle, rebounding out of your landing to hop back to where you started. Hop for a prescribed number or repetitions as quickly as possible, and finish this drill by sprinting a short distance upon landing the last hop.'),
('Side_Jackknife', 'Side Jackknife', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', NULL),
('Side_Lateral_Raise', 'Side Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position. While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a secon'),
('Side_Laterals_to_Front_Raise', 'Side Laterals to Front Raise', 'shoulders', ARRAY['back']::text[], 'dumbbell', 'strength', 'beginner', 'In a standing position, hold a pair of dumbbells at your side. This will be your starting position. Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. At the top of the exercise move the weights out in front of you, keeping your arms extended. Lower the weights with a controlled motion. On the next repetition, raise the weights in front of you to shoulder height before moving the weights laterally to your sides. Lo'),
('Side_Leg_Raises', 'Side Leg Raises', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position. Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg. Repeat this swinging motion 5-10 times, increasing the range of motion as you do so.'),
('Side_Lying_Groin_Stretch', 'Side Lying Groin Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Start off by lying on your right side and bend your right knee in front of you to stabilize the torso. Rest your head on your right hand or shoulder. Lift your left leg upward and hold it by the back of the knee (easier) or the foot (harder). Pull your left knee in toward your left shoulder and simultaneously press your foot or knee down to the floor. To intensify this stretch, straighten your left leg. Switch sides.'),
('Side_Neck_Stretch', 'Side Neck Stretch', 'other', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Start with your shoulders relaxed, gently tilt your head towards your shoulder. Assist stretch with a gentle pull on the side of the head.'),
('Side_Standing_Long_Jump', 'Side Standing Long Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Begin standing with your feet hip width apart in an athletic stance. Your head and chest should be up, knees and hips slightly bent. This will be your starting position. Leaning to your right, extend through your hips, knees, and ankles to jump into the air. Block with the arms to lead the movement, jumping as far to your right as you can. Land facing the same direction with your feet hip width apart, absorbing the impact through your lower body.'),
('Side_To_Side_Chins', 'Side To Side Chins', 'back', ARRAY['arms','arms','back','shoulders']::text[], 'other', 'strength', 'intermediate', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar at a wide grip, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position. Pull your torso up while leaning to the left hand side until the bar almost touches your upper chest by drawing the shoulders and the upper arms down and back. Exhale as you perform this portion of '),
('Side_Wrist_Pull', 'Side Wrist Pull', 'shoulders', ARRAY['arms','back']::text[], 'other', 'stretching', 'beginner', 'This stretch works best standing. Cross your left arm over the midline of your body and hold the left wrist in your right hand down at the level of your hips. Start the stretch with a bent left arm. Slowly straighten, pull, and lift it up to shoulder height, as pictured. Feel this stretch originate in your back, not your shoulders, and don''t pull too hard on the shoulders joint. Switch sides.'),
('Side_to_Side_Box_Shuffle', 'Side to Side Box Shuffle', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to one side of the box with your left foot resting on the middle of it. To begin, jump up and over to the other side of the box, landing with your right foot on top of the box and your left foot on the floor. Swing your arms to aid your movement. Continue shuffling back and forth across the box.'),
('Single-Arm_Cable_Crossover', 'Single-Arm Cable Crossover', 'chest', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. Step forward in front of both pulleys with your arms extended in front of you, bringing your hands together. Your head and chest should be up as you lean forward, while your feet should be staggered. This will be your starting position. Keeping your left arm in place, allow your right arm to extend out to the side, maintaining a slight bend at the elbow. The right arm should be per'),
('Single-Arm_Linear_Jammer', 'Single-Arm Linear Jammer', 'shoulders', ARRAY['chest','arms']::text[], 'barbell', 'strength', 'intermediate', 'Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight. Raise the bar from the floor, taking it to your shoulders with one or both hands. Adopt a wide stance. This will be your starting position. Perform the movement by extending the elbow, pressing the weight up. Move explosively, extending the hips and knees fully to produce maximal force. Return to the starting position.'),
('Single-Arm_Push-Up', 'Single-Arm Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'intermediate', 'Begin laying prone on the ground. Move yourself into a position supporting your weight on your toes and one arm. Your working arm should be placed directly under the shoulder, fully extended. Your legs should be extended, and for this movement you may need a wider base, placing your feet further apart than in a normal push-up. Maintain good posture, and place your free hand behind your back. This will be your starting position. Lower yourself by allowing the elbow to flex until you touch the gro'),
('Single-Cone_Sprint_Drill', 'Single-Cone Sprint Drill', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'This drill teaches quick foot action. You need a single cone. Begin standing next to the cone with one arm back and one arm forward. Chop the feet as quickly as possible, blocking with the arms. Circle the cone, keep your knees up, with violent foot action. Rest after three trips around the cone.'),
('Single-Leg_High_Box_Squat', 'Single-Leg High Box Squat', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'Position a box in a rack. Secure a band or rope in place above the box. Standing in front of it, step onto the box to a full standing position, letting your other leg remain unsupported. Hold onto the band for balance . Continue stepping up and down on the same leg before switching to the opposite side.'),
('Single-Leg_Hop_Progression', 'Single-Leg Hop Progression', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Arrange a line of cones in front of you. Assume a relaxed standing position, balanced on one leg. Raise the knee of your opposite leg. This will be your starting position. Hop forward, jumping and landing with the same leg over the cone. Use a countermovement jump to hop from cone to cone. At the end, turn around and go back on the other leg.'),
('Single-Leg_Lateral_Hop', 'Single-Leg Lateral Hop', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to the side of a cone or hurdle. To get into the start position, stand on one leg with your knee slightly bent. To begin, execute a counterjump to hop sideways over the cone. Land on your jumping leg, and immediately rebound out of it by jumping back to the start position. Continue hopping back and forth.'),
('Single-Leg_Leg_Extension', 'Single-Leg Leg Extension', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Seat yourself in the machine and adjust it so that you are positioned properly. The pad should be against the lower part of the shin but not in contact with the ankle. Adjust the seat so that the pivot point is in line with your knee. Select a weight appropriate for your abilities. Maintaining good posture, fully extend one leg, pausing at the top of the motion. Return to the starting position without letting the weight stop, keeping tension on the muscle. Repeat for the desired number of repeti'),
('Single-Leg_Stride_Jump', 'Single-Leg Stride Jump', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to the side of a box with your inside foot on top of it, close to the edge. Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward. Land in the same position that you started, using your inside leg to decelerate the impact.'),
('Single_Dumbbell_Raise', 'Single Dumbbell Raise', 'shoulders', ARRAY['arms','back']::text[], 'dumbbell', 'strength', 'beginner', 'With a wide stance, hold a dumbell with both hands, grasping the head of the dumbbell instead of the handle. Your arms should be extended and hanging at the waist. This will be your starting position. Raise the weight until it is above shoulder level, keeping your arms extended. Your torso and hips should remain stationary throughout the movement. Return to the starting position and repeat for the recommended amount of repetitions.'),
('Single_Leg_Butt_Kick', 'Single Leg Butt Kick', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Begin by standing on one leg, with the bent knee raised. This will be your start position. Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg. Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg. Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.'),
('Single_Leg_Glute_Bridge', 'Single Leg Glute Bridge', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'Lay on the floor with your feet flat and knees bent. Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position. Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground. Extend as far as possible, pause and then return to the starting position.'),
('Single_Leg_Push-off', 'Single Leg Push-off', 'legs', ARRAY['legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand on the ground with one foot resting on the box, heel close to the edge. Push off with your foot on top of the box, trying to gain as much height as possible by extending through the hip and knee. Land with the same foot on top of the box, returning your other foot back to the start position.'),
('Sit-Up', 'Sit-Up', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees. Place your hands behind your head and lock them together by clasping your fingers. This is the starting position. Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise. Once you feel the contraction for a second, lower your upper body back down to the starting po'),
('Sit_Squats', 'Sit Squats', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'stretching', 'beginner', 'Stand with your feet shoulder width apart. This will be your starting position. Begin the movement by flexing your knees and hips, sitting back with your hips. Continue until you have squatted a portion of the way down, but are above parallel, and quickly reverse the motion until you return to the starting position. Repeat for 5-10 repetitions.'),
('Skating', 'Skating', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'cardio', 'intermediate', 'Roller skating is a fun activity which can be effective in improving cardiorespiratory fitness and muscular endurance. It requires relatively good balance and coordination. It is necessary to learn the basics of skating including turning and stopping and to wear protective gear to avoid possible injury. You can skate at a comfortable pace for 30 minutes straight. If you want a cardio challenge, do interval skating — speed skate two minutes of every five minutes, using the remaining three minutes'),
('Sled_Drag_-_Harness', 'Sled Drag - Harness', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'strongman', 'beginner', 'To begin, load the sled with the desired weight and attach the pulling strap. You can pull with handles, use a harness, or attach the pulling strap to a weight belt. Whether pulling forwards or backwards, lean in the direction of travel and progress by extending through the hips and knees.'),
('Sled_Overhead_Backward_Walk', 'Sled Overhead Backward Walk', 'shoulders', ARRAY['legs','back','legs']::text[], 'other', 'strength', 'beginner', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight. Face the sled, backing up until there is some tension in the line. Hold your hands directly above your head with your elbows extended. This will be your starting position. Walk backwards, keeping your arms raised above your head. Avoid jerky movements.'),
('Sled_Overhead_Triceps_Extension', 'Sled Overhead Triceps Extension', 'arms', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Attach dual handles to a sled using a chain or rope. Load the sled to an appropriate load. Facing away from the sled, step away until there is tension in the line. Raise your hands above your head, keeping them together, palms facing each other. Your elbows should be pointed upward with the elbows flexed. This will be your starting position. Extend through the elbow to straighten the arm. Ensure that your upper arm stays in position to isolate the triceps. Upon full extension, step forward to ta'),
('Sled_Push', 'Sled Push', 'legs', ARRAY['legs','chest','legs','legs','arms']::text[], 'other', 'strongman', 'beginner', 'Load your pushing sled with the desired weight. Take an athletic posture, leaning into the sled with your arms fully extended, grasping the handles. Push the sled as fast as possible, focusing on extending your hips and knees to strengthen your posterior chain.'),
('Sled_Reverse_Flye', 'Sled Reverse Flye', 'shoulders', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to a light weight. Face the sled, backing up until there is some tension in the line. Take both handles at arms length at about waist level. Bend the knees slightly and keep your chest and head up. This will be your starting position. Without flexing the elbow, pull the handles upward and apart, performing a reverse fly with some external rotation. Your palms should be facing forward as you do this. Return to the starting '),
('Sled_Row', 'Sled Row', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'beginner', 'Attach dual handles to a sled connected by a rope or chain. Load the sled to an appropriate weight. Face the sled, backing up until there is some tension in the line. With a handle in each hand, bend the knees slightly, keep your head and chest up, and begin with your arms extended. To initiate the movement, flex the elbow as you retract your shoulder blades, pulling the sled towards you. Take a step or two back to get tension in the line and repeat.'),
('Sledgehammer_Swings', 'Sledgehammer Swings', 'core', ARRAY['legs','arms','back','back','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'You will need a tire and a sledgehammer for this exercise. Stand in front of the tire about two feet away from it with a staggered stance. Grip the sledgehammer. If you are right handed, your left hand should be at the bottom of the handle, and your right hand should be choking up closer to the head. As you bring the sledge up, your right hand slides toward the head; as you swing down, your right hand will slide down to join your left hand. Slam it down as hard as you can against the tire. Contr'),
('Smith_Incline_Shoulder_Raise', 'Smith Incline Shoulder Raise', 'shoulders', ARRAY['chest']::text[], 'barbell', 'strength', 'beginner', 'Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your shoulders are aligned right under the barbell. Using a shoulder width pronated (palms forward) grip, lift the bar from the rack and hold it straight over you with a slight bend at the elbows. This will be your starting position. As you breathe out, lift '),
('Smith_Machine_Behind_the_Back_Shrug', 'Smith Machine Behind the Back Shrug', 'back', ARRAY['shoulders']::text[], 'machine', 'strength', 'beginner', 'With the bar at thigh level, load an appropriate weight. Stand with the bar behind you, taking a shoulder-width, pronated grip on the bar and unhook the weight. You should be standing up straight with your head and chest up and your arms extended. This will be your starting position. Initiate the movement by shrugging your shoulders straight up. Do not flex the arms or wrist during the movement. After a brief pause return the weight to the starting position. Repeat for the desired number of repe'),
('Smith_Machine_Bench_Press', 'Smith Machine Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Place a flat bench underneath the smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. After a second pau'),
('Smith_Machine_Bent_Over_Row', 'Smith Machine Bent Over Row', 'back', ARRAY['arms','back','shoulders']::text[], 'machine', 'strength', 'beginner', 'Set the barbell attached to the smith machine to a height that is about 2 inches below your knees. Bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. Now grasp the barbell using an overhand (pronated) grip and unlock it from the smith machine rack. Then let it hang directly in front of you as your arms hang extended perpendicular to the floor and your t')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Smith_Machine_Calf_Raise', 'Smith Machine Calf Raise', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Place a block or weight plate below the bar on the Smith machine. Set the bar to a position that best matches your height. Once the correct height is chosen and the bar is loaded, step onto the plates with the balls of your feet and place the bar on the back of your shoulders. Take the bar with both hands facing forward. Rotate the bar to unrack it. This will be your starting position. Raise your heels as high as possible by pushing off of the balls of your feet, flexing your calf at the top of '),
('Smith_Machine_Close-Grip_Bench_Press', 'Smith Machine Close-Grip Bench Press', 'arms', ARRAY['chest','shoulders']::text[], 'machine', 'strength', 'beginner', 'Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle '),
('Smith_Machine_Decline_Press', 'Smith Machine Decline Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Position a decline bench in the rack so that the bar will be above your chest. Load an appropriate weight and take your place on the bench. Rotate the bar to unhook it from the rack and fully extend your arms. Your back should be slightly arched and your shoulder blades retracted. This will be your starting position. Begin the movement by flexing your arms, lowering the bar to your chest. Pause briefly, and then extend your arms to push the weight back to the starting position. After completing '),
('Smith_Machine_Hang_Power_Clean', 'Smith Machine Hang Power Clean', 'legs', ARRAY['legs','back','legs','shoulders','back']::text[], 'machine', 'strength', 'intermediate', 'Position the bar at knee height and load it to an appropriate weight. Take a pronated grip on the bar outside of shoulder width and unhook the bar from the machine. Your arms should be fully extended with your head and chest up. Your elbows should be pointed out with your shoulders back and down. Your hips should be back, loading the tension into the hamstrings. This will be your starting position. Initate the movement by forcefully extending the hips and knees, accelerating into the bar. Ensure'),
('Smith_Machine_Hip_Raise', 'Smith Machine Hip Raise', 'core', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Position a bench in the rack and load the bar to an appropriate weight. Lie down on the bench, placing the bottom of your feet against the bar. Unlock the bar and extend your legs. You may need to use your hands to assist you. For added stability grasp the sides of the Smith Machine. This will be your starting position. Initiate the movement by rotating your pelvis, flexing your spine to raise your hips off of the bench. Maintain a slight bend in the knees throughout the motion. After a brief pa'),
('Smith_Machine_Incline_Bench_Press', 'Smith Machine Incline Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe'),
('Smith_Machine_Leg_Press', 'Smith Machine Leg Press', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Position a Smith machine bar a couple feet off of the ground. Ensure that it is resting on the safeties. After loading the bar to an appropriate weight, lie underneath the bar. Place the middle of your feet on the bar, tucking your knees to your chest. This will be your starting position. Begin the movement by driving through your feet to move the bar upward, extending the hips and knees. Do not lock out your knees. At the top of the motion, pause briefly before returning to the starting positio'),
('Smith_Machine_One-Arm_Upright_Row', 'Smith Machine One-Arm Upright Row', 'shoulders', ARRAY['arms','back']::text[], 'machine', 'strength', 'beginner', 'With the bar at thigh level, load an appropriate weight. Take a wide grip on the bar and unhook the weight, removing your off hand from the bar. Your arm should be extended as you stand up straight with your head and chest up. This will be your starting position. Begin the movement by flexing the elbow, raising the upper arm with the elbow pointed out. Continue until your upper arm is parallel to the floor. After a brief pause, return the weight to the starting position. Repeat for the desired n'),
('Smith_Machine_Overhead_Shoulder_Press', 'Smith Machine Overhead Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'machine', 'strength', 'beginner', 'To begin, place a flat bench (or preferably one with back support) underneath a smith machine. Position the barbell at a height so that when seated on the flat bench, the arms must be almost fully extended to reach the barbell. Once you have the correct height, sit slightly in behind the barbell so that there is an imaginary straight line from the tip of your nose to the barbell. Your feet should be stationary. Grab the barbell with the palms facing forward, unlock it and lift it up so that your'),
('Smith_Machine_Pistol_Squat', 'Smith Machine Pistol Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'To begin, first set the bar to a position that best matches your height. Step under it and position the bar across the back of your shoulders. Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. 3 Move one foot forward about 12 inches in front of the bar. Extend the other leg out in front of you, holding it off the ground. Look forward at all times and maintain a neutral or slightly arched spine. This will be your starting position. Maintaining'),
('Smith_Machine_Reverse_Calf_Raises', 'Smith Machine Reverse Calf Raises', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the barbell on the smith machine to fit your height and align a raised platform right under the bar. Stand on the platform with the heels of your feet secured on top of it with the balls of your feet extending off it. Position your toes facing forward with a shoulder width stance. Now, place your shoulders under the barbell while maintaining the foot positioning described and push the barbell up by extending your hips and knees until your torso is standing erect. The knees should be kept '),
('Smith_Machine_Squat', 'Smith Machine Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'machine', 'strength', 'beginner', 'To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Position your legs using a shoulder width medium stance with the toes slightly pointed out.'),
('Smith_Machine_Stiff-Legged_Deadlift', 'Smith Machine Stiff-Legged Deadlift', 'legs', ARRAY['legs','back']::text[], 'machine', 'strength', 'beginner', 'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight. Lift the bar up by fully extending your arms while keeping your back straight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be'),
('Smith_Machine_Upright_Row', 'Smith Machine Upright Row', 'back', ARRAY['arms','back','shoulders']::text[], 'machine', 'strength', 'beginner', 'To begin, set the bar on the smith machine to a height that is around the middle of your thighs. Once the correct height is chosen and the bar is loaded, grasp the bar using a pronated (palms forward) grip that is shoulder width apart. You may need some wrist wraps if using a significant amount of weight. Lift the barbell up and fully extend your arms with your back straight. There should be a slight bend at the elbows. This is the starting position. Use your side shoulders to lift the bar as yo'),
('Smith_Single-Leg_Split_Squat', 'Smith Single-Leg Split Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'beginner', 'To begin, place a flat bench 2-3 feet behind the smith machine. Then, set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Position your legs by placing one foo'),
('Snatch', 'Snatch', 'legs', ARRAY['arms','legs','legs','back','shoulders','back','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Place your feet at a shoulder width stance with the barbell resting right above the connection between the toes and the rest of the foot. With a palms facing down grip, bend at the knees and keeping the back flat grab the bar using a wider than shoulder width grip. Bring the hips down and make sure that your body drops as if you were going to sit on a chair. This will be your starting position. Start pushing the floor as if it were a moving platform with your feet and simultaneously start liftin'),
('Snatch_Balance', 'Snatch Balance', 'legs', ARRAY['legs','legs','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with the feet in the pulling position, the bar racked across the back of the shoulders, and the hands placed in a wide snatch grip. Pop the bar with an abrupt dip and drive of the knees, and aggressively drive under the bar, transitioning the feet into the receiving position. Receive the bar locked out overhead near the bottom of the squat. The torso should remain vertical, lowering the hips between the legs. Continue to descend to full depth, and return to a standing position. Carefully l'),
('Snatch_Deadlift', 'Snatch Deadlift', 'legs', ARRAY['arms','legs','legs','back','legs','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'The snatch deadlift strengthens the first pull of the snatch. Begin with a wide snatch grip with the barbell placed on the platform. The feet should be directly under the hips, with the feet turned out. Squat down to the bar, keeping the back in absolute extension with the head facing forward. Initiate the movement by driving through the heels, raising the hips. The back angle should remain the same until the bar passes the knees. At that point, drive your hips through the bar as you lay back. R'),
('Snatch_Pull', 'Snatch Pull', 'legs', ARRAY['legs','legs','back','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'With a barbell on the floor close to the shins, take a wide snatch grip. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes the second pull, th'),
('Snatch_Shrug', 'Snatch Shrug', 'back', ARRAY['arms','shoulders']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a wide grip, with the bar hanging at the mid thigh position. You can use a hook or overhand grip. Your back should be straight and inclined slightly forward. Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a snatch, avoid overloading to the point that the execution slows down.'),
('Snatch_from_Blocks', 'Snatch from Blocks', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a loaded barbell on boxes or stands of the desired height. A wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar, with the elbows pointed out. This will be the starting position. Begin the first pull by driving through the front of the heels, raising the bar from the boxes. Transition into the second pull by '),
('Speed_Band_Overhead_Triceps', 'Speed Band Overhead Triceps', 'arms', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'For this exercise anchor a band to the ground. We used an incline bench and anchored the band to the base, standing over the bench. Alternatively, this could be performed standing on the band. To begin, pull the band behind your head, holding it with a pronated grip and your elbows up. This will be your starting position. To perform the movement, extend through the elbow to to straighten your arms, ensuring that you keep your upper arm in place. Pause, and then return to the starting position.'),
('Speed_Box_Squat', 'Speed Box Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'powerlifting', 'intermediate', 'Attach bands to the bar that are securely anchored near the ground. You may need to choke the bands to get adequate tension. Use a box of an appropriate height for this exercise. Load the bar to a weight that still requires effort, but isn''t so heavy that speed is compromised. Typically, that will be between 50-70% of your one rep max. Position the bar on your upper back, shoulder blades retracted, back arched and everything tight head to toe. This will be the starting position. Unrack the bar '),
('Speed_Squats', 'Speed Squats', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'expert', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a s'),
('Spell_Caster', 'Spell Caster', 'core', ARRAY['legs','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell in each hand with a pronated grip. Your feet should be wide with your hips and knees extended. This will be your starting position. Begin the movement by pulling both of the dumbbells to one side next to your hip, rotating your torso. Keeping your arms straight and the dumbbells parallel to the ground, rotate your torso to swing the weights to your opposite side. Continue alternating, rotating from one side to the other until the set is complete.'),
('Spider_Crawl', 'Spider Crawl', 'core', ARRAY['chest','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Begin in a prone position on the floor. Support your weight on your hands and toes, with your feet together and your body straight. Your arms should be bent to 90 degrees. This will be your starting position. Initiate the movement by raising one foot off of the ground. Externally rotate the leg and bring the knee toward your elbow, as far forward as possible. Return this leg to the starting position and repeat on the opposite side.'),
('Spider_Curl', 'Spider Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start out by setting the bar on the part of the preacher bench that you would normally sit on. Make sure to align the barbell properly so that it is balanced and will not fall off. Move to the front side of the preacher bench (the part where the arms usually lay) and position yourself to lay at a 45 degree slant with your torso and stomach pressed against the front side of the preacher bench. Make sure that your feet (especially the toes) are well positioned on the floor and place your upper arm'),
('Spinal_Stretch', 'Spinal Stretch', 'back', ARRAY['back','back','other','back']::text[], 'other', 'stretching', 'beginner', 'Sit in a chair so your back is straight and your feet planted on the floor. Interlace your fingers behind your head, elbows out and your chin down. Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee. Return to upright position and then repeat for your other side.'),
('Split_Clean', 'Split Clean', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on the floor close to the shins, take an overhand grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Next comes'),
('Split_Jerk', 'Split Jerk', 'legs', ARRAY['legs','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as'),
('Split_Jump', 'Split Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Assume a lunge stance position with one foot forward with the knee bent, and the rear knee nearly touching the ground. Ensure that the front knee is over the midline of the foot. Extending through both legs, jump as high as possible, swinging your arms to gain lift. As you jump, bring your feet together, and move them back to their initial positions as you land. Absorb the impact by reverting back to the starting position.'),
('Split_Snatch', 'Split Snatch', 'legs', ARRAY['legs','arms','legs','legs','back','legs','shoulders','back','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a loaded barbell on the floor. The bar should be close to or touching the shins, and a wide grip should be taken on the bar. The feet should be directly below the hips, with the feet turned out as needed. Lower the hips, with the chest up and the head looking forward. The shoulders should be just in front of the bar. This will be the starting position. Begin the first pull by driving through the front of the heels, raising the bar from the ground. The back angle should stay the same u'),
('Split_Squat_with_Dumbbells', 'Split Squat with Dumbbells', 'legs', ARRAY['legs','legs']::text[], 'dumbbell', 'strength', 'beginner', 'Position yourself into a staggered stance with the rear foot elevated and front foot forward. Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position. Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise. At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position.'),
('Split_Squats', 'Split Squats', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'stretching', 'intermediate', 'Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so. As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.'),
('Squat_Jerk', 'Squat Jerk', 'legs', ARRAY['legs','legs','legs','shoulders','arms']::text[], 'barbell', 'strength', 'expert', 'Standing with the weight racked on the front of the shoulders, begin with the dip. With your feet directly under your hips, flex the knees without moving the hips backward. Go down only slightly, and reverse direction as powerfully as possible. Drive through the heels create as much speed and force as possible, and be sure to move your head out of the way as the bar leaves the shoulders. At this moment as the feet leave the floor, the feet must be placed into the receiving position as quickly as'),
('Squat_with_Bands', 'Squat with Bands', 'legs', ARRAY['legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch in your lower back, and step back into position. Place your feet wide for more emphasis on the back, glutes, adductors, and '),
('Squat_with_Chains', 'Squat with Chains', 'legs', ARRAY['legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders. Remove the bar from the rack, creating a tight arch i'),
('Squat_with_Plate_Movers', 'Squat with Plate Movers', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'barbell', 'strength', 'intermediate', 'To begin, first set the bar on a rack to just below shoulder level. Position a weight plate on the ground a couple feet back from the rack. Once the bar is loaded, step under it and place the back of your shoulders across it. Hold on to the bar with both hands and lift it off the rack by first pushing with your legs and at the same time straighten your torso. Step away from the rack and adopt a wide stance with the toes slightly pointed out, with one foot on the weight plate. Keep your head up a'),
('Squats_-_With_Bands', 'Squats - With Bands', 'legs', ARRAY['legs','legs','legs','back']::text[], 'bands', 'strength', 'beginner', 'To start out, make sure that the exercise band is at an even split between both the left and right side of the body. To do this, use your hands to grab both sides of the band and place both feet in the middle of the band. Your feet should be shoulder width apart from each other. When holding the bands, they should be the same height on each side. You should be using a pronated grip (palms facing forward) and have the handles of the bands next to your face for this exercise. This is the starting '),
('Stairmaster', 'Stairmaster', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'intermediate', 'To begin, step onto the stairmaster and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Pump your legs up and down in an established rhythm, driving the pedals down but not all the way to the floor. It is recommended that you maintain your grip on the handles so that you don''t fall. The handles can be used to monitor your heart rat'),
('Standing_Alternating_Dumbbell_Press', 'Standing Alternating Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Stand with a dumbbell in each hand. Raise the dumbbells to your shoulders with your palms facing forward and your elbows pointed out. This will be your starting position. Extend one arm to press the dumbbell straight up, keeping your off hand in place. Do not lean or jerk the weight during the movement. After a brief pause, return the weight to the starting position. Repeat for the opposite side, continuing to alternate between arms.'),
('Standing_Barbell_Calf_Raise', 'Standing Barbell Calf Raise', 'legs', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the bar on the back of your shoulders (slightly below the neck). Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a '),
('Standing_Barbell_Press_Behind_Neck', 'Standing Barbell Press Behind Neck', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for easier pick up of the bar. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs'),
('Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension', 'Standing Bent-Over One-Arm Dumbbell Triceps Extension', 'arms', ARRAY['shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'With a dumbbell in one hand and the palm facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arm should be close to the torso and parallel to the floor while the forearm is pointing towards the floor as the hand holds the weight. Tip: There should be a 90-degree angle between the forearm and the upper arm. This is your starting po'),
('Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension', 'Standing Bent-Over Two-Arm Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'With a dumbbell in each hand and the palms facing your torso, bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Make sure that you keep the head up. The upper arms should be close to the torso and parallel to the floor while the forearms are pointing towards the floor as the hands hold the weights. Tip: There should be a 90-degree angle between the forearms and the upper arm. This is your star'),
('Standing_Biceps_Cable_Curl', 'Standing Biceps Cable Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder l'),
('Standing_Biceps_Stretch', 'Standing Biceps Stretch', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'stretching', 'beginner', 'Clasp your hands behind your back with your palms together, straighten arms and then rotate them so your palms face downward. Raise your arms up and hold until you feel a stretch in your biceps.'),
('Standing_Bradford_Press', 'Standing Bradford Press', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Place a loaded bar at shoulder level in a rack. With a pronated grip at shoulder width, begin with the bar racked across the front of your shoulders. This is your starting position. Initiate the lift by extending the elbows to press the bar overhead. Avoid locking out the elbow as you move the weight behind your head. Lower the bar down to the back of the head until your elbow forms a right angle. Lift the bar back over your head by extending the elbows Lower the bar down to the starting positio'),
('Standing_Cable_Chest_Press', 'Standing Cable Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Position dual pulleys to chest height and select an appropriate weight. Stand a foot or two in front of the cables, holding one in each hand. You can stagger your stance for better stability. Position the upper arm at a 90 degree angle with the shoulder blades together. This will be your starting position. Keeping the rest of the body stationary, extend through the elbows to press the handles forward, drawing them together in front of you. Pause at the top of the motion, and return to the starti'),
('Standing_Cable_Lift', 'Standing Cable Lift', 'core', ARRAY['shoulders']::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle on a tower, and move the cable to the lowest pulley position. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable. With your feet positioned shoulder width apart, squat down and grab the handle with both hands. Your arms should still be fully extended. In one motion, pull ')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Standing_Cable_Wood_Chop', 'Standing Cable Wood Chop', 'core', ARRAY['shoulders']::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to a tower, and move the cable to the highest pulley position. With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable. With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extend'),
('Standing_Calf_Raises', 'Standing Calf Raises', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the padded lever of the calf raise machine to fit your height. Place your shoulders under the pads provided and position your toes facing forward (or using any of the two other positions described at the beginning of the chapter). The balls of your feet should be secured on top of the calf block with the heels extending off it. Push the lever up by extending your hips and knees until your torso is standing erect. The knees should be kept with a slight bend; never locked. Toes should be fa'),
('Standing_Concentration_Curl', 'Standing Concentration Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Taking a dumbbell in your working hand, lean forward. Allow your working arm to hang perpendicular to the ground with the elbow pointing out. This will be your starting position. Flex the elbow to curl the weight, keeping the upper arm stationary. At the top of the repetition, flex the biceps and pause. Lower the dumbbell back to the starting position. Repeat the movement for the prescribed amount of repetitions.'),
('Standing_Dumbbell_Calf_Raise', 'Standing Dumbbell Calf Raise', 'legs', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Stand with your torso upright holding two dumbbells in your hands by your sides. Place the ball of the foot on a sturdy and stable wooden board (that is around 2-3 inches tall) while your heels extend off and touch the floor. This will be your starting position. With the toes pointing either straight (to hit all parts equally), inwards (for emphasis on the outer head) or outwards (for emphasis on the inner head), raise the heels off the floor as you exhale by contracting the calves. Hold the top'),
('Standing_Dumbbell_Press', 'Standing Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Standing with your feet shoulder width apart, take a dumbbell in each hand. Raise the dumbbells to head height, the elbows out and about 90 degrees. This will be your starting position. Maintaining strict technique with no leg drive or leaning back, extend through the elbow to raise the weights together directly above your head. Pause, and slowly return the weight to the starting position.'),
('Standing_Dumbbell_Reverse_Curl', 'Standing Dumbbell Reverse Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'To begin, stand straight with a dumbbell in each hand using a pronated grip (palms facing down). Your arms should be fully extended while your feet are shoulder width apart from each other. This is the starting position. While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a seco'),
('Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head', 'Standing Dumbbell Straight-Arm Front Delt Raise Above Head', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Hold the dumbbells in front of your thighs, palms facing your thighs. Keep your arms straight with a slight bend at the elbows but keep them locked. This will be your starting position. Raise the dumbbells in a semicircular motion to arm''s length overhead as you exhale. Slowly return to the starting position using the same path as you inhale. Repeat for the recommended amount of repetitions.'),
('Standing_Dumbbell_Triceps_Extension', 'Standing Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended. The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position. Keeping your upper arms close to your head with elbows in and perpendicular to the floo'),
('Standing_Dumbbell_Upright_Row', 'Standing Dumbbell Upright Row', 'back', ARRAY['arms','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Grasp a dumbbell in each hand with a pronated (palms forward) grip that is slightly less than shoulder width. The dumbbells should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be close to the body as you move it up and the elbows should drive the motion. Continue to lift them until they nearly t'),
('Standing_Elevated_Quad_Stretch', 'Standing Elevated Quad Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Start by standing with your back about two to three feet away from a bench or step. Lift one leg behind you and rest your foot on the step,either on your instep or the ball of your foot, whichever you find most comfortable. Keep your supporting knee slightly bent and avoid letting that knee extend out beyond your toes. Switch sides.'),
('Standing_Front_Barbell_Raise_Over_Head', 'Standing Front Barbell Raise Over Head', 'shoulders', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'To begin, stand straight with a barbell in your hands. You should grip the bar with palms facing down and a closer than shoulder width grip apart from each other. Your feet should be shoulder width apart from each other. Your elbows should be slightly bent. This is the starting position. Lift the barbell up until it is directly over your head while exhaling. Make sure to keep your elbows slightly bent when performing each repetition. Once you feel the contraction, begin to lower the barbell back'),
('Standing_Gastrocnemius_Calf_Stretch', 'Standing Gastrocnemius Calf Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Place your right heel on a step with your knee extended and lean forward to grab your right toe with your right hand. Your left knee should be slightly bent and your back should be straight. Support your weight on your left leg and place your left hand on your left thigh. Pull your right toes toward your knee until you feel a stretch in your calf.'),
('Standing_Hamstring_and_Calf_Stretch', 'Standing Hamstring and Calf Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Being by looping a belt, band, or rope around one foot. While standing, place that foot forward. Bend your back leg, while keeping the front one straight. Now raise the toes of your front foot off of the ground and lean forward. Using the belt, pull on the top of the foot to increase the stretch in the calf. Hold for 10-20 seconds and repeat with the other foot.'),
('Standing_Hip_Circles', 'Standing Hip Circles', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'beginner', 'Begin standing on one leg, holding to a vertical support. Raise the unsupported knee to 90 degrees. This will be your starting position. Open the hip as far as possible, attempting to make a big circle with your knee. Perform this movement slowly for a number of repetitions, and repeat on the other side.'),
('Standing_Hip_Flexors', 'Standing Hip Flexors', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand up straight with the spine vertical, the left foot slightly in front of the right. Bend both knees and lift the back heel off the floor as you press the right hip forward. You can''t get a thorough, deep stretch in this position, however, because it''s hard to relax the hip flexor and stand on it at the same time. Switch sides.'),
('Standing_Inner-Biceps_Curl', 'Standing Inner-Biceps Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Stand up with a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Your legs should be at about shoulder''s width apart from each other. Rotate the palms of the hands so that they are facing inward in a neutral position. This will be your starting position. While holding the upper arms stationary, curl the weights out while contracting the biceps as you breathe out. Your wrist should turn so that when the weights are fully elevated you have supinated grip ('),
('Standing_Lateral_Stretch', 'Standing Lateral Stretch', 'core', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Take a slightly wider than hip distance stance with your knees slightly bent. Place your right hand on your right hip to support the spine. Raise your left arm in a vertical line and place your left hand behind your head. Keep it there as you incline your torso to the right. Keep your weight evenly distributed between both legs (don''t lean into your left hip). Switch sides.'),
('Standing_Leg_Curl', 'Standing Leg Curl', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the machine lever to fit your height and lie with your torso bent at the waist facing forward around 30-45 degrees (since an angled position is more favorable for hamstrings recruitment) with the pad of the lever on the back of your right leg (just a few inches under the calves) and the front of the right leg on top of the machine pad. Keeping the torso bent forward, ensure your leg is fully stretched and grab the side handles of the machine. Position your toes straight. This will be your'),
('Standing_Long_Jump', 'Standing Long Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'This drill is best done in sand or other soft landing surface. Ensure that you are able to measure distance. Stand in a partial squat stance with feet shoulder width apart. Utilizing a big arm swing and a countermovement of the legs, jump forward as far as you can. Attempt to land with your feet out in front you, reaching as far as possible with your legs. Measure the distance from your landing point to the starting point and track results.'),
('Standing_Low-Pulley_Deltoid_Raise', 'Standing Low-Pulley Deltoid Raise', 'shoulders', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Start by standing to the right side of a low pulley row. Use your left hand to come across the body and grab a single handle attached to the low pulley with a pronated grip (palms facing down). Rest your arm in front of you. Your right hand should grab the machine for better support and balance. Make sure that your back is erect and your feet are shoulder width apart from each other. This is the starting position. Begin to use the left hand and come across your body out until it is elevated to s'),
('Standing_Low-Pulley_One-Arm_Triceps_Extension', 'Standing Low-Pulley One-Arm Triceps Extension', 'arms', ARRAY['chest','shoulders']::text[], 'cable', 'strength', 'intermediate', 'Grab a single handle with your left arm next to the low pulley machine. Turn away from the machine keeping the handle to the side of your body with your arm fully extended. Now use both hands to elevate the single handle directly above the head with the palm facing forward. Keep your upper arm completely vertical (perpendicular to the floor) and put your right hand on your left elbow to help keep it steady. This is the starting position. Keeping your upper arms close to your head (elbows in) and'),
('Standing_Military_Press', 'Standing Military Press', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Start by placing a barbell that is about chest high on a squat rack. Once you have selected the weights, grab the barbell using a pronated (palms facing forward) grip. Make sure to grip the bar wider than shoulder width apart from each other. Slightly bend the knees and place the barbell on your collar bone. Lift the barbell up keeping it lying on your chest. Take a step back and position your feet shoulder width apart from each other. Once you pick up the barbell with the correct grip length, l'),
('Standing_Olympic_Plate_Hand_Squeeze', 'Standing Olympic Plate Hand Squeeze', 'arms', ARRAY['arms']::text[], 'other', 'strength', 'beginner', 'To begin, stand straight while holding a weight plate by the ridge at arm''s length in each hand using a neutral grip (palms facing in). You feet should be shoulder width apart from each other. This will be your starting position. Lower the plates until the fingers are nearly extended but can still hold weights. Inhale as you lower the plates. Now raise the plates back to the starting position as you exhale by closing your hands. Repeat for the recommended amount of repetitions prescribed in you'),
('Standing_One-Arm_Cable_Curl', 'Standing One-Arm Cable Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'Start out by grabbing single handle next to the low pulley machine. Make sure you are far enough from the machine so that your arm is supporting the weight. Make sure that your upper arm is stationary, perpendicular to the floor with elbows in and palms facing forward. Your non lifting arm should be grabbing your waist. This will allow you to keep your balance. Slowly begin to curl the single handle upwards while keeping the upper arm stationary until your forearm touches your bicep while exhali'),
('Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench', 'Standing One-Arm Dumbbell Curl Over Incline Bench', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand on the back side of an incline bench as if you were going to be a spotter for someone. Have a dumbbell in one hand and rest it across the incline bench with a supinated (palms up) grip. Position your non lifting hand at the corner or side of the incline bench. The chest should be pressed against the top part of the incline and your feet should be pressed against the floor at a wide stance. This is the starting position. While holding the upper arm stationary, curl the dumbbell upward while'),
('Standing_One-Arm_Dumbbell_Triceps_Extension', 'Standing One-Arm Dumbbell Triceps Extension', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'To begin, stand up with a dumbbell held in one hand. Your feet should be about shoulder width apart from each other. Now fully extend the arm with the dumbbell over your head. Tip: The small finger of your hand should be facing the ceiling and the palm of your hand should be facing forward. The dumbbell should be above your head. This will be your starting position. Keeping your upper arm close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion'),
('Standing_Overhead_Barbell_Triceps_Extension', 'Standing Overhead Barbell Triceps Extension', 'arms', ARRAY['shoulders']::text[], 'barbell', 'strength', 'beginner', 'To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart. Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position. Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your'),
('Standing_Palm-In_One-Arm_Dumbbell_Press', 'Standing Palm-In One-Arm Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Start by having a dumbbell in one hand with your arm fully extended to the side using a neutral grip. Use your other arm to hold on to an incline bench to keep your balance. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbell up until you create a 90 degree angle with your arm. Note: Your forearm should be perpendicular to the floor. Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbell up until your arm is fully extended.'),
('Standing_Palms-In_Dumbbell_Press', 'Standing Palms-In Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Start by having a dumbbell in each hand with your arm fully extended to the side using a neutral grip. Your feet should be shoulder width apart from each other. Now slowly lift the dumbbells up until you create a 90 degree angle with your arms. Note: Your forearms should be perpendicular to the floor. This the starting position. Continue to maintain a neutral grip throughout the entire exercise. Slowly lift the dumbbells up until your arms are fully extended. While inhaling lower the weights dow'),
('Standing_Palms-Up_Barbell_Behind_The_Back_Wrist_Curl', 'Standing Palms-Up Barbell Behind The Back Wrist Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Start by standing straight and holding a barbell behind your glutes at arm''s length while using a pronated grip (palms will be facing back away from the glutes) and having your hands shoulder width apart from each other. You should be looking straight forward while your feet are shoulder width apart from each other. This is the starting position. While exhaling, slowly elevate the barbell up by curling your wrist in a semi-circular motion towards the ceiling. Note: Your wrist should be the only'),
('Standing_Pelvic_Tilt', 'Standing Pelvic Tilt', 'back', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Start off with your feet hip-distance apart. Bend your knees slightly to keep them soft and springy. You may want to move your pelvis forward and backward and back few times before holding the tailbone forward in this stretch.'),
('Standing_Rope_Crunch', 'Standing Rope Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope to a high pulley and select an appropriate weight. Stand with your back to the cable tower. Take the rope with both hands over your shoulders, holding it to your upper chest. This will be your starting position. Perform the movement by flexing the spine, crunching the weight down as far as you can. Hold the peak contraction for a moment before returning to the starting position.'),
('Standing_Soleus_And_Achilles_Stretch', 'Standing Soleus And Achilles Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand with your feet hip-distance apart, one foot slightly in front of the other. Bend both knees, keeping your back heel on the floor. Switch sides.'),
('Standing_Toe_Touches', 'Standing Toe Touches', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Stand with some space in front and behind you. Bend at the waist, keeping your legs straight, until you can relax and let your upper body hang down in front of you. Let your arms and hands hang down naturally. Hold for 10 to 20 seconds.'),
('Standing_Towel_Triceps_Extension', 'Standing Towel Triceps Extension', 'arms', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position. Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower'),
('Standing_Two-Arm_Overhead_Throw', 'Standing Two-Arm Overhead Throw', 'shoulders', ARRAY['chest','back']::text[], 'other', 'plyometrics', 'beginner', 'Stand with your feet shoulder width apart holding a medicine ball in both hands. To begin, reach the medicine ball deep behind your head as you bend the knees slightly and lean back. Violently throw the ball forward, flexing at the hip and using your whole body to complete the movement. The medicine ball can be thrown to a partner or to a wall, receiving it as it bounces back.'),
('Star_Jump', 'Star Jump', 'legs', ARRAY['legs','legs','legs','shoulders']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body. To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body. As you land, bring your limbs back in and absorb your impact through the legs.'),
('Step-up_with_Knee_Raise', 'Step-up with Knee Raise', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position. Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can. Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.'),
('Step_Mill', 'Step Mill', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'intermediate', 'To begin, step onto the stepmill and select the desired option from the menu. You can choose a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Use caution so that you don''t trip as you climb the stairs. It is recommended that you maintain your grip on the handles so that you don''t fall. Stepmills offer convenience, cardiovascular benefits, and usually have less impact than running outsid'),
('Stiff-Legged_Barbell_Deadlift', 'Stiff-Legged Barbell Deadlift', 'legs', ARRAY['legs','back']::text[], 'barbell', 'strength', 'intermediate', 'Grasp a bar using an overhand grip (palms facing down). You may need some wrist wraps if using a significant amount of weight. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position. Keeping the knees stationary, lower the barbell to over the top of your feet by bending at the hips while keeping your back straight. Keep moving forward as if you were going to pick something from the floor unt'),
('Stiff-Legged_Dumbbell_Deadlift', 'Stiff-Legged Dumbbell Deadlift', 'legs', ARRAY['legs','back']::text[], 'dumbbell', 'strength', 'beginner', 'Grasp a couple of dumbbells holding them by your side at arm''s length. Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position. Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as y'),
('Stiff_Leg_Barbell_Good_Morning', 'Stiff Leg Barbell Good Morning', 'back', ARRAY['legs','legs']::text[], 'barbell', 'strength', 'beginner', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a s'),
('Stomach_Vacuum', 'Stomach Vacuum', 'core', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'To begin, stand straight with your feet shoulder width apart from each other. Place your hands on your hips. This is the starting position. Now slowly inhale as much air as possible and then start to exhale as much as possible while bringing your stomach in as much as possible and hold this position. Try to visualize your navel touching your backbone. One isometric contraction is around 20 seconds. During the 20 second hold, try to breathe normally. Then inhale and bring your stomach back to the'),
('Straight-Arm_Dumbbell_Pullover', 'Straight-Arm Dumbbell Pullover', 'chest', ARRAY['back','shoulders','arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well. Grasp the dumbbell with both hands and hold it straight over your chest at arms length. Both palms should be pressing against the underside one of'),
('Straight-Arm_Pulldown', 'Straight-Arm Pulldown', 'back', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so. Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten t'),
('Straight_Bar_Bench_Mid_Rows', 'Straight Bar Bench Mid Rows', 'back', ARRAY['arms','back']::text[], 'barbell', 'strength', 'beginner', 'Place a loaded barbell on the end of a bench. Standing on the bench behind the bar, take a medium, pronated grip. Stand with your hips back and chest up, maintaining a neutral spine. This will be your starting position. Row the bar to your torso by retracting the shoulder blades and flexing the elbows. Use a controlled movement with no jerking. After a brief pause, slowly return the bar to the starting position, ensuring to go all the way down.'),
('Straight_Raises_on_Incline_Bench', 'Straight Raises on Incline Bench', 'shoulders', ARRAY['back']::text[], 'barbell', 'strength', 'beginner', 'Place a bar on the ground behind the head of an incline bench. Lay on the bench face down. With a pronated grip, pick the barbell up from the floor, keeping your arms straight. Allow the bar to hang straight down. This will be your starting position. To begin, raise the barbell out in front of your head while keeping your arms extended. Return to the starting position.'),
('Stride_Jump_Crossover', 'Stride Jump Crossover', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand to the side of a box with your inside foot on top of it, close to the edge. Begin by swinging the arms upward as you push through the top leg, jumping upward as high as possible. Attempt to drive the opposite knee upward. Land in the opposite position that you started, on the opposite side of the box. The foot that was initially on the box will now be on the ground, with the opposite foot now on the box. Repeat the movement, crossing back over to the other side.'),
('Sumo_Deadlift', 'Sumo Deadlift', 'legs', ARRAY['legs','arms','legs','back','back','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a mixed grip, or hook grip. Relax the shoulders, which in effect lengthens your arms. Take a breath, and then lower your hips, looking forward with your head with your chest up. Drive through the floor, sprea'),
('Sumo_Deadlift_with_Bands', 'Sumo Deadlift with Bands', 'legs', ARRAY['legs','arms','legs','back','back','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. Ensure that they under the back half of your foot, directly where you are driving into the floor. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside the legs, and you can use a pronated grip, a ')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Sumo_Deadlift_with_Chains', 'Sumo Deadlift with Chains', 'legs', ARRAY['legs','legs','arms','legs','back','back','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Attempt to keep the ends of the chains away from the plates so you don''t hit them when you lower the weight. Begin with a bar loaded on the ground. Approach the bar so that the bar intersects the middle of the feet. The feet should be set very wide, near the collars. Bend at the hips to grip the bar. The arms should be directly below the shoulders, inside'),
('Superman', 'Superman', 'back', ARRAY['legs','legs']::text[], 'bodyweight', 'stretching', 'beginner', 'To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position. Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying. Slowly begin to lower your arms, legs'),
('Supine_Chest_Throw', 'Supine Chest Throw', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'This drill is great for chest passes when you lack a partner or a wall of sufficient strength. Lay on the ground on your back with your knees bent. Begin with the ball on your chest, held with both hands on the bottom. Explode up, extending through the elbow to throw the ball directly above you as high as possible. Catch the ball with both hands as it comes down.'),
('Supine_One-Arm_Overhead_Throw', 'Supine One-Arm Overhead Throw', 'core', ARRAY['chest','back','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'Lay on the ground on your back with your knees bent. Hold the ball with one hand, extending the arm fully behind your head. This will be your starting position. Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. The ball can be thrown to a partner or bounced off of a wall.'),
('Supine_Two-Arm_Overhead_Throw', 'Supine Two-Arm Overhead Throw', 'core', ARRAY['chest','back','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'Lay on the ground on your back with your knees bent. Hold the ball with both hands, extending the arms fully behind your head. This will be your starting position. Initiate the movement at the shoulder, throwing the ball directly forward of you as you sit up, attempting to go for maximum distance. The ball can be thrown to a partner or bounced off of a wall.'),
('Suspended_Fallout', 'Suspended Fallout', 'core', ARRAY['chest','back','shoulders']::text[], 'other', 'strength', 'intermediate', 'Adjust the straps so the handles are at an appropriate height, below waist level. Begin standing and grasping the handles. Lean into the straps, moving to an incline push-up position. This will be your starting position. Keeping your arms straight, lean further into the suspension straps, bringing your body closer to the ground, allowing your shoulders to extend, raising your arms up and over your head. Maintain a neutral spine and keep the rest of your body straight, your shoulders being the on'),
('Suspended_Push-Up', 'Suspended Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'strength', 'beginner', 'Anchor your suspension straps securely to the top of a rack or other object. Leaning into the straps, take a handle in each hand and move into a push-up plank position. You should be as close to parallel to the ground as you can manage with your arms fully extended, maintaining good posture. Maintaining a straight, rigid torso, descend slowly by allowing the elbows to flex. Continue until your elbows break 90 degrees, pausing before you extend to return to the starting position.'),
('Suspended_Reverse_Crunch', 'Suspended Reverse Crunch', 'core', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Secure a set of suspension straps with the handles hanging about a foot off of the ground. Move yourself into a pushup plank position facing away from the rack. Place your feet into the handles. You should maintain a straight posture, not allowing the hips to sag. This will be your starting position. Begin the movement by flexing the knees and hips, drawing the knees to your torso. As you do so, anteriorly tilt your pelvis, allowing your spine to flex. At the top of the controlled motion, return'),
('Suspended_Row', 'Suspended Row', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'beginner', 'Suspend your straps at around chest height. Take a handle in each hand and lean back. Keep your body erect and your head and chest up. Your arms should be fully extended. This will be your starting position. Begin by flexing the elbow to initiate the movement. Protract your shoulder blades as you do so. At the completion of the motion pause, and then return to the starting position.'),
('Suspended_Split_Squat', 'Suspended Split Squat', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'strength', 'intermediate', 'Suspend your straps so the handles are 18-30 inches from the floor. Facing away from the setup, place your rear foot into the handle behind you. Keep your head looking forward and your chest up, with your knee slightly bent. This will be your starting position. Descend by flexing the knee and hips, lowering yourself to the ground. Keep your weight on the heel of your foot and maintain your posture throughout the exercise. At the bottom of the movement, reverse the motion, extending through the h'),
('Svend_Press', 'Svend Press', 'chest', ARRAY['arms','shoulders','arms']::text[], 'other', 'strength', 'beginner', 'Begin in a standing position. Press two lightweight plates together with your hands. Hold the plates together close to your chest to create an isometric contraction in your chest muscles. Your fingers should be pointed forward. This is your starting position. Squeeze the plates between your palms and extend your arms directly out in front of you in a controlled motion. Pause at the top of the motion, and then slowly return to the starting position.'),
('T-Bar_Row_with_Handle', 'T-Bar Row with Handle', 'back', ARRAY['arms','back']::text[], 'barbell', 'strength', 'beginner', 'Position a bar into a landmine or in a corner to keep it from moving. Load an appropriate weight onto your end. Stand over the bar, and position a Double D row handle around the bar next to the collar. Using your hips and legs, rise to a standing position. Assume a wide stance with your hips back and your chest up. Your arms should be extended. This will be your starting position. Pull the weight to your upper abdomen by retracting the shoulder blades and flexing the elbows. Do not jerk the weig'),
('Tate_Press', 'Tate Press', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'strength', 'intermediate', 'Lie down on a flat bench with a dumbbell in each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them in front of you at shoulder width. Note: when holding the dumbbells in front of you, make sure your arms are wider than shoulder width apart from each other using a pronated (palms forward) grip. Allow your elbows to point out. This is your starting posi'),
('The_Straddle', 'The Straddle', 'legs', ARRAY['legs','legs']::text[], 'other', 'stretching', 'beginner', 'Begin in a seated, upright position. Start by extending your legs in front of you in a V. With your hands on the floor, lean forward as far as possible. Hold for 10 to 20 seconds.'),
('Thigh_Abductor', 'Thigh Abductor', 'legs', ARRAY['legs']::text[], 'machine', 'strength', 'beginner', 'To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position. Slowly press against the machine with your legs to move them away from each other while exhaling. Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper '),
('Thigh_Adductor', 'Thigh Adductor', 'legs', ARRAY['legs','legs']::text[], 'machine', 'strength', 'beginner', 'To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position. Slowly press against the machine with your legs to move them towards each other while exhaling. Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note:'),
('Tire_Flip', 'Tire Flip', 'legs', ARRAY['legs','chest','arms','legs','legs','back','shoulders','back','arms']::text[], 'other', 'strongman', 'intermediate', 'Begin by gripping the bottom of the tire on the tread, and position your feet back a bit. Your chest should be driving into the tire. To lift the tire, extend through the hips, knees, and ankles, driving into the tire and up. As the tire reaches a 45 degree angle, step forward and drive a knee into the tire. As you do so adjust your grip to the upper portion of the tire and push it forward as hard as possible to complete the turn. Repeat as necessary.'),
('Toe_Touchers', 'Toe Touchers', 'core', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down. Your legs should be touching each other. Slowly elevate your legs up in the air until they are almost perpendicular to the floor with a slight bend at the knees. Your feet should be parallel to the floor. Move your arms so that they are fully extended at a 45 degree angle from the floor. This is the starting position. While keeping y'),
('Torso_Rotation', 'Torso Rotation', 'core', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position. Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions.'),
('Trail_Running_Walking', 'Trail Running/Walking', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'cardio', 'beginner', 'Running or hiking on trails will get the blood pumping and heart beating almost immediately. Make sure you have good shoes. While you use the muscles in your calves and buttocks to pull yourself up a hill, the knees, joints and ankles absorb the bulk of the pounding coming back down. Take smaller steps as you walk downhill, keep your knees bent to reduce the impact and slow down to avoid falling. A 150 lb person can burn over 200 calories for 30 minutes walking uphill, compared to 175 on a flat '),
('Trap_Bar_Deadlift', 'Trap Bar Deadlift', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'For this exercise load a trap bar, also known as a hex bar, to an appropriate weight resting on the ground. Stand in the center of the apparatus and grasp both handles. Lower your hips, look forward with your head and keep your chest up. Begin the movement by driving through the heels and extend your hips and knees. Avoid rounding your back at all times. At the completion of the movement, lower the weight back to the ground under control.'),
('Tricep_Dumbbell_Kickback', 'Tricep Dumbbell Kickback', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Start with a dumbbell in each hand and your palms facing your torso. Keep your back straight with a slight bend in the knees and bend forward at the waist. Your torso should be almost parallel to the floor. Make sure to keep your head up. Your upper arms should be close to your torso and parallel to the floor. Your forearms should be pointed towards the floor as you hold the weights. There should be a 90-degree angle formed between your forearm and upper arm. This is your starting position. Now,'),
('Tricep_Side_Stretch', 'Tricep Side Stretch', 'arms', ARRAY['shoulders']::text[], 'other', 'stretching', 'beginner', 'Bring right arm across your body and over your left shoulder, holding your elbow with your left hand, until you feel a stretch in your tricep. Then repeat for your other arm.'),
('Triceps_Overhead_Extension_with_Rope', 'Triceps Overhead Extension with Rope', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable. Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position. To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your he'),
('Triceps_Pushdown', 'Triceps Pushdown', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width. Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position. Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicu'),
('Triceps_Pushdown_-_Rope_Attachment', 'Triceps Pushdown - Rope Attachment', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other). Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position. Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the '),
('Triceps_Pushdown_-_V-Bar_Attachment', 'Triceps Pushdown - V-Bar Attachment', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width. Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position. Using the triceps, bring the bar down until it touches the front of your thighs and the '),
('Triceps_Stretch', 'Triceps Stretch', 'arms', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides.'),
('Tuck_Crunch', 'Tuck Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'To begin, lie down on the floor or an exercise mat with your back pressed against the floor. Your arms should be lying across your sides with the palms facing down. Your legs should be crossed by wrapping one ankle around the other. Slowly elevate your legs up in the air until your thighs are perpendicular to the floor with a slight bend at the knees. Note: Your knees and toes should be parallel to the floor as opposed to the thighs. Move your arms from the floor and cross them so they are resti'),
('Two-Arm_Dumbbell_Preacher_Curl', 'Two-Arm Dumbbell Preacher Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Grab a dumbbell with each arm and place the upper arms on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position. As you breathe in, slowly lower the dumbbells until your upper arm is extended and the biceps is fully stretched. As you exhale, use the biceps to curl the weights up until your biceps is fully contracted and the dumbbells are at shoulder height. Squeeze the biceps hard for a second at the contracted positio'),
('Two-Arm_Kettlebell_Clean', 'Two-Arm Kettlebell Clean', 'shoulders', ARRAY['legs','legs','legs','back','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean the kettlebells to your shoulders by extending through the legs and hips as you raise the kettlebells towards your shoulders. Rotate your wrists as you do so. Lower the kettlebells back to the starting position and repeat.'),
('Two-Arm_Kettlebell_Jerk', 'Two-Arm Kettlebell Jerk', 'shoulders', ARRAY['legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Squat down a few inches and reverse the motion rapidly driving both kettlebells overhead. Immediately after the initial push, squat down again and get under the kettlebells. Once the kettlebells are locked out, stand upright to complete the exercise.'),
('Two-Arm_Kettlebell_Military_Press', 'Two-Arm Kettlebell Military Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you swing the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. Press the kettlebells up and out. As the kettlebells pass your head, lean into the weights so that the kettlebells are racked behind your head. Make sure to contract your lats, butt, and stomach for added stability.'),
('Two-Arm_Kettlebell_Row', 'Two-Arm Kettlebell Row', 'back', ARRAY['arms','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells in front of your feet. Bend your knees slightly and then push your butt out as much as possible as you bend over to get in the starting position. Grab both kettlebells and pull them to your stomach, retracting your shoulder blades and flexing the elbows. Keep your back straight. Lower and repeat.'),
('Underhand_Cable_Pulldowns', 'Underhand Cable Pulldowns', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'beginner', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width. As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so'),
('Upper_Back-Leg_Grab', 'Upper Back-Leg Grab', 'legs', ARRAY['back','back']::text[], 'other', 'stretching', 'beginner', 'While seated, bend forward to hug your thighs from underneath with both arms. Keep your knees together and your legs extended out as you bring your chest down to your knees. You can also stretch your middle back by pulling your back away from your knees as your hugging them.'),
('Upper_Back_Stretch', 'Upper Back Stretch', 'back', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward.'),
('Upright_Barbell_Row', 'Upright Barbell Row', 'shoulders', ARRAY['back']::text[], 'barbell', 'strength', 'beginner', 'Grasp a barbell with an overhand grip that is slightly less than shoulder width. The bar should be resting on the top of your thighs with your arms extended and a slight bend in your elbows. Your back should also be straight. This will be your starting position. Now exhale and use the sides of your shoulders to lift the bar, raising your elbows up and to the side. Keep the bar close to your body as you raise it. Continue to lift the bar until it nearly touches your chin. Tip: Your elbows should '),
('Upright_Cable_Row', 'Upright Cable Row', 'back', ARRAY['shoulders']::text[], 'cable', 'strength', 'intermediate', 'Grasp a straight bar cable attachment that is attached to a low pulley with a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The bar should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the cable bar as you exhale. The bar should be close to the body as you move it up. Continue to lift it until it nearly touc'),
('Upright_Row_-_With_Bands', 'Upright Row - With Bands', 'back', ARRAY['shoulders']::text[], 'bands', 'strength', 'beginner', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on top of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the handles as you exhale. The handles should be close to the body as you move them up. Continu'),
('Upward_Stretch', 'Upward Stretch', 'shoulders', ARRAY['chest','back']::text[], 'other', 'stretching', 'beginner', 'Extend both hands straight above your head, palms touching. Slowly push your hands up and back, keeping your back straight.'),
('V-Bar_Pulldown', 'V-Bar Pulldown', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'intermediate', 'Sit down on a pull-down machine with a V-Bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position. Using your lats, pull the bar down as you squeeze your shoulder blade'),
('V-Bar_Pullup', 'V-Bar Pullup', 'back', ARRAY['arms','back','shoulders']::text[], 'bodyweight', 'strength', 'beginner', 'Start by placing the middle of the V-bar in the middle of the pull-up bar (assuming that the pull-up station you are using does not have neutral grip handles). The V-Bar handles will be facing down so that you can hang from the pull-up bar through the use of the handles. Once you securely place the V-bar, take a hold of the bar from each side and hang from it. Stick your chest out and lean yourself back slightly in order to better engage the lats. This will be your starting position. Using your '),
('Vertical_Swing', 'Vertical Swing', 'legs', ARRAY['legs','legs','shoulders']::text[], 'dumbbell', 'plyometrics', 'beginner', 'Allow the dumbbell to hang at arms length between your legs, holding it with both hands. Keep your back straight and your head up. Swing the dumbbell between your legs, flexing at the hips and bending the knees slightly. Powerfully reverse the motion by extending at the hips, knees, and ankles to propel yourself upward, swinging the dumbell over your head. As you land, absorb the impact through your legs and draw the dumbbell to your torso before the next repetition.'),
('Walking_Treadmill', 'Walking, Treadmill', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'beginner', 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than walking outside. When walking, you should move at a moderate to fast pace, not a leisur'),
('Weighted_Ball_Hyperextension', 'Weighted Ball Hyperextension', 'back', ARRAY['legs','legs','back']::text[], 'other', 'strength', 'intermediate', 'To begin, lie down on an exercise ball with your torso pressing against the ball and parallel to the floor. The ball of your feet should be pressed against the floor to help keep you balanced. Place a weighted plate under your chin or behind your neck. This is the starting position. Slowly raise your torso up by bending at the waist and lower back. Remember to exhale during this movement. Hold the contraction on your lower back for a second and lower your torso back down to the starting position'),
('Weighted_Ball_Side_Bend', 'Weighted Ball Side Bend', 'core', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'To begin, lie down on an exercise ball with your left side of the torso (waist, hips and shoulder) pressed against the ball. Your feet should be on the floor while your legs are crossed and hanging from the ball. Hold a weighted plate with your right hand directly to the right side of your head. Tip: Make sure the smooth side of the plate is resting against your head. Place your left arm across your torso so that your palm is on your obliques. There should be a right angle between your left fore'),
('Weighted_Bench_Dip', 'Weighted Bench Dip', 'arms', ARRAY['chest','shoulders']::text[], 'other', 'strength', 'intermediate', 'For this exercise you will need to place a bench behind your back and another one in front of you. With the benches perpendicular to your body, hold on to one bench on its edge with the hands close to your body, separated at shoulder width. Your arms should be fully extended. The legs will be extended forward on top of the other bench. Your legs should be parallel to the floor while your torso is to be perpendicular to the floor. Have your partner place the dumbbell on your lap. Note: This exerc'),
('Weighted_Crunches', 'Weighted Crunches', 'core', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Lie flat on your back with your feet flat on the ground or resting on a bench with your knees bent at a 90 degree angle. Hold a weight to your chest, or you may hold it extended above your torso. This will be your starting position. Now, exhale and slowly begin to roll your shoulders off the floor. Your shoulders should come up off the floor about 4 inches while your lower back remains on the floor. At the top of the movement, flex your abdominals and hold for a brief pause. Then inhale and slow'),
('Weighted_Jump_Squat', 'Weighted Jump Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'Position a lightly loaded barbell across the back of your shoulders. You could also use a weighted vest, sandbag, or other type of resistance for this exercise. The weight should be light enough that it doesn''t slow you down significantly. Your feet should be just outside of shoulder width with your head and chest up. This will be your starting position. Using a countermovement, squat partially down and immediately reverse your direction to explode off of the ground, extending through your hips')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Weighted_Pull_Ups', 'Weighted Pull Ups', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'intermediate', 'Attach a weight to a dip belt and secure it around your waist. Grab the pull-up bar with the palms of your hands facing forward. For a medium grip, your hands should be spaced at shoulder width. Both arms should be extended in front of you holding the bar at the chosen grip. You''ll want to bring your torso back about 30 degrees while creating a curvature in your lower back and sticking your chest out. This will be your starting position. Now, exhale and pull your torso up until your head is abo'),
('Weighted_Sissy_Squat', 'Weighted Sissy Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'expert', 'Standing upright, with feet at shoulder width and toes raised, use one hand to hold onto the beams of a squat rack and the opposite arm to hold a plate on top of your chest. This is your starting position. As you use one arm to hold yourself, bend at the knees and slowly lower your torso toward the ground by bringing your pelvis and knees forward. Inhale as you go down and stop when your upper and lower legs almost create a 90-degree angle. Hold the stretch position for a second. After your one '),
('Weighted_Sit-Ups_-_With_Bands', 'Weighted Sit-Ups - With Bands', 'core', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Start out by strapping the bands around the base of the decline bench. Place the handles towards the inside of the decline bench so that when lying down, you can reach for both of them. Position your legs through the decline machine until they are secured. Now reach for the exercise bands with both hands. Use a pronated (palms forward) grip to grasp the handles. Position them near your collar bone and rotate your wrist to a neutral grip (palms facing the torso). Note: Your arms should remain sta'),
('Weighted_Squat', 'Weighted Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'strength', 'intermediate', 'Start by positioning two flat benches shoulder width apart from each other. Stand on top of them and wrap the weighted belt around your waist with the amount of weight you feel comfortable with. Make sure your toes are facing out. Once you are standing straight up with the weight hanging in between your legs, position your arms so that they are fully extended to the side of your body. This is the starting position. Begin by bending the knees as you maintain a straight posture with the head up. C'),
('Wide-Grip_Barbell_Bench_Press', 'Wide-Grip Barbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie back on a flat bench with feet firm on the floor. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. After a second pause, bring the bar back to the starting position as you breathe'),
('Wide-Grip_Decline_Barbell_Bench_Press', 'Wide-Grip Decline Barbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie back on a decline bench with the feet securely locked at the front of the bench. Using a wide, pronated (palms forward) grip that is around 3 inches away from shoulder width (for each hand), lift the bar from the rack and hold it straight over you with your arms locked. The bar will be perpendicular to the torso and the floor. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your lower chest. After a second pause, bring the bar back to the st'),
('Wide-Grip_Decline_Barbell_Pullover', 'Wide-Grip Decline Barbell Pullover', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie down on a decline bench with both legs securely locked in position. Reach for the barbell behind the head using a pronated grip (palms facing out). Make sure to grab the barbell wider than shoulder width apart for this exercise. Slowly lift the barbell up from the floor by using your arms. When positioned properly, your arms should be fully extended and perpendicular to the floor. This is the starting position. Begin by moving the barbell back down in a semicircular motion as if you were goi'),
('Wide-Grip_Lat_Pulldown', 'Wide-Grip Lat Pulldown', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'beginner', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your sho'),
('Wide-Grip_Pulldown_Behind_The_Neck', 'Wide-Grip Pulldown Behind The Neck', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'intermediate', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to you'),
('Wide-Grip_Rear_Pull-Up', 'Wide-Grip Rear Pull-Up', 'back', ARRAY['arms','back','shoulders']::text[], 'bodyweight', 'strength', 'intermediate', 'Grab the pull-up bar with the palms facing forward using a wide grip. As you have both arms extended in front of you holding the bar, bring your torso forward and head so that there is an imaginary line from the pull-up bar to the back of your neck. This is your starting position. Pull your torso up until the bar is near the back of your neck. To do this, draw the shoulders and upper arms down and back while slightly leaning your head forward. Exhale as you perform this portion of the movement. '),
('Wide-Grip_Standing_Barbell_Curl', 'Wide-Grip Standing Barbell Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Stand up with your torso upright while holding a barbell at the wide outer handle. The palm of your hands should be facing forward. The elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second an'),
('Wide_Stance_Barbell_Squat', 'Wide Stance Barbell Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a w'),
('Wide_Stance_Stiff_Legs', 'Wide Stance Stiff Legs', 'legs', ARRAY['legs','legs','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a barbell loaded on the floor. Adopt a wide stance, and then bend at the hips to grab the bar. Your hips should be as far back as possible, and your legs nearly straight. Keep your back straight, and your head and chest up. This will be your starting position. Begin the movement be engaging the hips, driving them forward as you allow the arms to hang straight. Continue until you are standing straight up, and then slowly return the weight to the starting position. For successive reps, '),
('Wind_Sprints', 'Wind Sprints', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Hang from a pull-up bar using a pronated grip. Your arms and legs should be extended. This will be your starting position. Begin by quickly raising one knee as high as you can. Do not swing your body or your legs. 3 Immediately reverse the motion, returning that leg to the starting position. Simultaneously raise the opposite knee as high as possible. Continue alternating between legs until the set is complete.'),
('Windmills', 'Windmills', 'legs', ARRAY['legs','legs','back']::text[], 'other', 'stretching', 'intermediate', 'Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position. Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand. Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions.'),
('Worlds_Greatest_Stretch', 'World''s Greatest Stretch', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'stretching', 'intermediate', 'This is a three-part stretch. Begin by lunging forward, with your front foot flat on the ground and on the toes of your back foot. With your knees bent, squat down until your knee is almost touching the ground. Keep your torso erect, and hold this position for 10-20 seconds. Now, place the arm on the same side as your front leg on the ground, with the elbow next to the foot. Your other hand should be placed on the ground, parallel to your lead leg, to help support you during this portion of the '),
('Wrist_Circles', 'Wrist Circles', 'arms', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Start by standing straight with your feet being shoulder width apart from each other. Elevate your arms to the side of you until they are fully extended and parallel to the floor at a height that is evenly aligned with your shoulders. Tip: Your torso and arms should form the letter "T: Your palms should be facing down. This is the starting position. Keeping your entire body stationary except for the wrists, begin to rotate both wrists forward in a circular motion. Tip: Pretend that you are tryin'),
('Wrist_Roller', 'Wrist Roller', 'arms', ARRAY['shoulders']::text[], 'other', 'strength', 'beginner', 'To begin, stand straight up grabbing a wrist roller using a pronated grip (palms facing down). Your feet should be shoulder width apart. Slowly lift both arms until they are fully extended and parallel to the floor in front of you. Note: Make sure the rope is not wrapped around the roller. Your entire body should be stationary except for the forearms. This is the starting position. Rotate one wrist at a time in an upward motion to bring the weight up to the bar by rolling the rope around the rol'),
('Wrist_Rotations_with_Straight_Bar', 'Wrist Rotations with Straight Bar', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands and your palms facing down; hands spaced about shoulder width. This will be your starting position. Alternating between each of your hands, perform the movement by extending the wrist as though you were rolling up a newspaper. Continue alternating back and forth until failure. Reverse the motion by flexing the wrist, rolling the opposite direction. Continue the alternating motion until failure.'),
('Yoke_Walk', 'Yoke Walk', 'legs', ARRAY['core','legs','legs','legs','legs','legs','back']::text[], 'other', 'strongman', 'intermediate', 'The yoke is usually done with a yoke apparatus, but is sometimes seen with refrigerators or other heavy objects. Begin by racking the apparatus across the back of the shoulders. With your head looking forward and back arched, lift the yoke by driving through the heels. Begin walking as quickly as possible using short, quick steps. You may hold the side posts of the yoke to help steady it and hold it in position. Continue for the given distance as fast as possible, usually 75-100 feet.'),
('Zercher_Squats', 'Zercher Squats', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'expert', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. The correct height should be anywhere above the waist but below the chest. Once the correct height is chosen and the bar is loaded, lock your hands together and place the bar on top of your arms in between the forearm and upper arm. Lift the bar up so that it is resting on top of your forearms. If you are holding the bar properly, it should look as if you '),
('Zottman_Curl', 'Zottman Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. Make sure the palms of the hands are facing each other. This will be your starting position. While holding the upper arm stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Your wrist should rotate so that you have a supinated (palms up) grip. Continue the movement until your biceps are fully contracted and the d'),
('Zottman_Preacher_Curl', 'Zottman Preacher Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Grab a dumbbell in each hand and place your upper arms on top of the preacher bench or the incline bench. The dumbbells should be held at shoulder height and the elbows should be flexed. Hold the dumbbells with the palms of your hands facing down. This will be your starting position. As you breathe in, slowly lower the dumbbells keeping the palms down until your upper arm is extended and your biceps are fully stretched. Now rotate your wrists once you are at the bottom of the movement so that th')
